/**
 * 영업일 훅 — 오늘 값을 언제 굳히고 언제 푸는가.
 *
 * 사장님 결정: **영업 시작 시점의 판매가·재료 구성·단가·부자재·고정지출·세금으로
 * 하루가 고정된다.** 영업 중에 레시피를 고쳐도 오늘 매출·원가·손익은 안 움직이고,
 * 레시피 화면에는 새 값이 보인다("지금 팔면 얼마 남나"는 다른 질문이라서다).
 * 고친 값은 **다음 영업일 기준**부터 매출에 들어간다.
 *
 * 그래서 매출 등록 전에 영업이 시작돼 있어야 한다. 시작 전이면 서버가 45001 으로
 * 막고, 화면은 "오늘 영업을 시작할까요?"를 먼저 묻는다.
 */
import { useEffect } from 'react';
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { invalidate, invalidateOn, qk } from '@/lib/queryClient';
import { rpcNullableString as str, rpcNumber as num } from '@/lib/rpcValue';
import { supabase, RpcError, rpcError } from '@/lib/supabase';
import { useStoreId } from '@/lib/SessionProvider';

/** 'none' = 오늘 아직 시작 전 · 'closed' = 오늘 이미 끝냄. 화면이 다른 것을 그린다. */
export type BusinessDayStatus = 'none' | 'open' | 'break' | 'closed';

/*
 * ⚠ 여기 있던 `AutoCloseNotice` 와 `BusinessDayState.unacked` 를 지웠다(0141).
 *   자동 종료 확인 배너는 기획에서 삭제됐다 — §5-4 "예정 종료는 정상 동작이므로
 *   매일 확인 배너를 띄우지 않는다". 서버의 `unacked` 키·`ack_auto_close`·
 *   `unacked_auto_close`·`auto_close_ack` 컬럼도 같이 걷어냈다.
 *   직접 종료와 자동 종료는 `closeMethod` 로만 구분한다(§6.1).
 */


export interface BusinessDayState {
  /**
   * 판매 영업일 기준의 오늘(cutoff 반영). 3단계에서 정리된다.
   * ⚠ `localDate` 와 다른 값이다 — 지금은 cutoff 가 0 이라 같아 보일 뿐이다.
   */
  today: string;
  /**
   * **매장 달력의 오늘**(0125). 영업시간과 무관하다.
   * 발주·입고·재고·레시피 화면이 쓸 날짜다 — 거기서는 판매 영업일이 아니라 달력 날짜가 맞다.
   * ⚠ 앱이 직접 계산하지 않는다. 예전엔 `+09:00` 고정 오프셋으로 만들었고,
   *   그래서 앱과 DB 가 각자 오늘을 계산했다(기획서 §2.1).
   */
  localDate: string;
  /** 매장 시간대(0162). 종료 시각 표시·늦은 개점 기본값이 **매장 현지** 기준이어야 한다. */
  timezone: string;
  status: BusinessDayStatus;
  businessDayId: string | null;
  businessDate: string;
  openedAt: string | null;
  plannedCloseAt: string | null;
  closedAt: string | null;
  closeMethod: 'manual' | 'auto' | null;
  /*
   * ⚠ `autoCloseAt`·`pastPlanned`·`warnSoon`·`due` 를 지웠다(0142).
   *   타입 선언과 파싱만 있고 **그리는 자리가 하나도 없었다.** 기획서 §6.1 의
   *   `영업 중` 규격에도 그런 예고가 없다 — 카드는 `영업일 + 시간 + 상태/행동`
   *   한 줄뿐이다. 서버의 `auto_close_due()` 도 이 응답을 만들려고만 있어 같이 지웠다.
   *   §5-4 가 확인 배너를 없앤 것과 같은 결정이다.
   *
   *   자동으로 닫혔다는 사실은 `closeMethod` 로 안다. 마감 시각을 미리 알리는 UI 를
   *   만들게 되면 그때 다시 세운다 — 껍데기로 남겨 두지 않는다.
   */
  /**
   * 열려 있는 영업일이 **오늘이 아니다**(businessDate ≠ today).
   * 이때 오늘 매출은 서버가 45001 로 막는다 — 바가 '영업 중'만 말하면 안 된다.
   */
  staleDay: boolean;
  hours: {
    openTime: string | null;
    closeTime: string | null;
    breakStart: string | null;
    breakEnd: string | null;
    /** 종료가 시작보다 이르면 자정을 넘긴다(10:00~02:00). */
    overnight: boolean;
  };
}

function parse(raw: unknown): BusinessDayState {
  const r = (raw ?? {}) as Record<string, unknown>;
  const h = (r.hours ?? {}) as Record<string, unknown>;
  return {
    today: reqDate(r.today, 'today'),
    /*
     * ⚠ **`today` 로 대신 메우지 않는다.** 예전엔 `r.local_date ?? r.today` 였는데,
     *   그러면 서버가 필드를 빠뜨려도 정상처럼 보이고 세 날짜를 가른 의미가 사라진다.
     *
     * ⚠ 빈 문자열로 넘기지도 않는다. 그러면 `error` 가 null 인 채 날짜만 없어서
     *   게이트가 **오류도 로딩도 아닌 빈 화면**을 그린다 — 사장님은 다시 시도할
     *   길이 없다. 없거나 모양이 틀리면 **던진다.**
     */
    localDate: reqDate(r.local_date, 'local_date'),
    // ⚠ 조용한 기본값 금지 — 시간대가 빠지면 종료 시각이 기기 시간대로 그려진다(P2-6).
    timezone: (() => {
      const tz = typeof r.timezone === 'string' ? r.timezone : '';
      if (tz === '') throw new Error('서버 응답에 timezone 이 없어요. 잠시 후 다시 시도해 주세요');
      return tz;
    })(),
    status: (r.status ?? 'none') as BusinessDayStatus,
    businessDayId: str(r.business_day_id),
    businessDate: reqDate(r.business_date, 'business_date'),
    openedAt: str(r.opened_at),
    plannedCloseAt: str(r.planned_close_at),
    closedAt: str(r.closed_at),
    closeMethod: (str(r.close_method) as 'manual' | 'auto' | null) ?? null,
    // 열린 날이 오늘이 아니면 오늘 매출은 서버가 막는다. 화면이 알아야 한다.
    staleDay:
      (r.status === 'open' || r.status === 'break') &&
      String(r.business_date ?? '') !== String(r.today ?? ''),
    hours: {
      openTime: str(h.open_time),
      closeTime: str(h.close_time),
      breakStart: str(h.break_start),
      breakEnd: str(h.break_end),
      overnight: h.overnight === true,
    },
  };
}

/** 'YYYY-MM-DD' 만 통과시킨다. 날짜 권위를 서버로 옮겼으므로 모양이 틀리면 그건 사고다. */
const YMD = /^\d{4}-\d{2}-\d{2}$/;
function reqDate(v: unknown, field: string): string {
  const t = typeof v === 'string' ? v : '';
  if (!YMD.test(t)) {
    throw new Error(`서버가 날짜를 주지 않았어요 (${field}). 잠시 후 다시 시도해 주세요`);
  }
  return t;
}

export function useBusinessDay() {
  const storeId = useStoreId();
  return useQuery({
    queryKey: qk.businessDay,
    enabled: Boolean(storeId),
    queryFn: async (): Promise<BusinessDayState> => {
      /*
       * ⚠ **조회만 한다.** 예전엔 여기서 `close_if_due()` 를 같이 불렀다 —
       *   서버에 스케줄러가 없어 누군가 불러 줘야 했고, 상태를 보는 이 순간을
       *   그 자리로 삼았다.
       *
       *   그런데 날짜 권위를 서버로 옮기면서 이 훅이 **날짜 조회의 통로**가 됐다.
       *   그러면 폐기 내역·입고 등록·발주 화면을 **여는 것만으로 영업이 종료된다.**
       *   "날짜를 묻는 것" 과 "영업을 끝내는 것" 은 같은 문으로 들어오면 안 된다.
       *
       *   지금 자동 종료는 **서버 pg_cron 만** 실행한다(0137·0139). 앱은 관여하지 않는다 —
       *   `useAutoCloseSweep()` 도 지웠다. 앱이 실행 주체이던 시절의 흔적이 없어야
       *   "화면을 여니 영업이 끝났다" 가 다시 생기지 않는다.
       */
      const { data, error } = await supabase.rpc('business_day_state', { p_store: storeId });
      if (error) throw new Error(error.message);
      return parse(data);
    },
    /*
     * 화면을 열어 둔 채로도 상태가 바뀐다 — **크론이 닫기 때문이다.**
     * ⚠ 예전엔 "자동 종료가 다가오는지" 를 갱신하려던 것이었는데, 그 예고
     *   (`auto_close_at`·`warn_soon` 등)는 그리는 자리가 없어 지웠다(0142).
     *   지금 이 주기의 목적은 하나다 — 크론이 바꾼 종료 상태를 따라잡는 것.
     */
    refetchInterval: 60_000,
    refetchOnWindowFocus: true,
  });
}

/*
 * ⚠ 여기 있던 `useAutoCloseSweep()` 을 지웠다(0137).
 *
 *   그건 서버에 스케줄러가 없던 시절의 임시방편이었다 — 앱이 1분마다 `close_if_due` 를
 *   불러 줘야 어제 영업일이 닫혔고, 앱을 안 열면 안 닫혔다(기획서 §2.4).
 *   실제로 8/22 장부에 `8/23 08:25` 가 찍혀 있었다.
 *
 *   이제 `close_due_business_days()` 를 pg_cron 이 1분마다 돈다. 앱은 관여하지 않는다.
 *
 *   ⚠ 남겨 뒀다면 **판정이 두 곳**이 됐을 것이다. 그때는 규칙까지 서로 달랐다 —
 *     앱 경로는 `마지막 활동 + 1시간` 이라 활동이 있으면 밀렸고, 서버 스윕은
 *     `예정 종료 + 고정 유예` 라 안 밀렸다. (0139 에서 서버 쪽도 한 식으로 통일했고,
 *      앱 경로는 여기서 아예 없앴다.)
 */

/**
 * 상태 전이 — 한 문(0157). open · start_break · resume · end.
 * 서버 몸통이 행을 잠그고 상태를 재확인하며 감사 기록을 남긴다.
 * 틀린 전이(이미 브레이크인데 또 브레이크 등)는 45014,
 * 규칙 종료가 지난 시각의 시작은 45015(늦은 개점 — 종료 시간을 골라 다시)로 온다.
 */
function useTransition(action: 'open' | 'start_break' | 'resume' | 'end') {
  const qc = useQueryClient();
  const storeId = useStoreId();
  return useMutation({
    mutationFn: async (arg?: { closeTime?: string }): Promise<void> => {
      const { error } = await supabase.rpc('transition_business_state', {
        p_store: storeId, p_action: action,
        p_close_time: arg?.closeTime ?? undefined,
      });
      // ⚠ 코드를 살려 던진다(0145) — 화면이 45015 를 문구가 아니라 코드로 가른다.
      if (error) throw rpcError(error);
    },
    onSuccess: () => invalidate(qc, invalidateOn.businessDay()),
  });
}

/** 영업 시작 — 이 시점 값으로 오늘이 굳는다. */
export function useOpenBusinessDay() {
  return useTransition('open');
}

/**
 * 브레이크타임 — 같은 영업일을 유지한다. 오늘 기준값도 그대로다.
 * ⚠ 옛 set_break 은 상태값만 바꿨다(검사·기록 없음) — 0157 에서 지웠다.
 *   설정된 브레이크 시간의 자동 전환(크론)도 같은 서버 몸통을 쓴다.
 */
export function useSetBreak() {
  const start = useTransition('start_break');
  const resume = useTransition('resume');
  return {
    mutate: (on: boolean, opts?: { onError?: (e: Error) => void }) =>
      (on ? start : resume).mutate(undefined, opts),
    isPending: start.isPending || resume.isPending,
  };
}

/** 영업 종료 — 그날 장부를 집계해 함께 남기고 잠근다. */
export function useCloseBusinessDay() {
  return useTransition('end');
}

/**
 * 어제 걸 닫고 오늘을 연다 — **한 번에**.
 *
 * 안 닫힌 날이 남아 있으면 오늘 매출이 서버에서 45001 로 막힌다. 예전엔 사장님이
 * `종료` 누르고 `영업 시작` 을 또 눌러야 했는데, 화면은 그때 초록 '영업중' 배지를
 * 달고 있었다 — 뭘 눌러야 하는지 알 길이 없었다. 버튼 하나로 끝낸다.
 *
 * ⚠ 이제 **RPC 도 한 번이다**(0154). 예정 종료가 지난 옛 날은 `open_business_day` 가
 *   같은 트랜잭션에서 닫고 연다 — close → open 두 번이던 시절엔 사이에 다른 기기가
 *   끼어들 수 있었다. 기한(유예)까지 지난 날은 auto(예정 시각 기록), 유예 안이면
 *   manual(지금 시각)로 닫힌다.
 * ⚠ 어제 기준값은 어제 것 그대로 잠긴 채로 닫힌다. 오늘 것만 지금 값으로 굳는다.
 */
export function useCloseStaleAndOpen() {
  const qc = useQueryClient();
  const storeId = useStoreId();
  return useMutation({
    mutationFn: async (arg?: { closeTime?: string }): Promise<void> => {
      const opened = await supabase.rpc('transition_business_state', {
        p_store: storeId, p_action: 'open',
        p_close_time: arg?.closeTime ?? undefined,
      });
      if (opened.error) throw rpcError(opened.error);
    },
    onSuccess: () => invalidate(qc, invalidateOn.businessDay()),
  });
}

/*
 * ⚠ 여기 있던 `useReopenBusinessDay()` 와 `useAckAutoClose()` 를 지웠다(0140).
 *
 *   **되열기** — 기획서 §6.4 가 "종료된 장부를 다시 열지 않는다" 로 정했고, 0139 에서
 *   서버가 실제로 그렇게 됐다. 화면에 되열기 버튼이 없는데 훅만 남아 있으면
 *   다음 사람이 "이미 있는 기능" 으로 읽고 다시 붙인다.
 *   과거 판매 수정은 정정 RPC(`amend_ended_business_day`)가 맡는다(0145·0146).
 *
 *   **자동 종료 확인** — `BusinessDayBar` 가 선언만 해 두고 한 번도 안 썼다.
 *   기획서 §5-4 가 "예정 종료는 정상 동작이므로 매일 확인 배너를 띄우지 않는다" 로
 *   정했으므로 서버의 `ack_auto_close`·`unacked_auto_close` 와 `auto_close_ack`
 *   컬럼도 **같이 지웠다**(0141). 되살릴 자리를 남기지 않는다.
 */

/*
 * 서버가 왜 막았는가 — **코드로** 가른다(0145).
 *
 * ⚠ 예전엔 한국어 문구를 검사했다. 그래서 0140 에서 문구를 고칠 때 여기도 같이 고쳐야
 *   했고, 한쪽만 고치면 화면이 오류를 못 알아봤다. 문구는 사람이 읽는 것이고 코드는
 *   화면이 읽는 것이다 — 둘을 묶어 두면 문구를 못 고친다.
 *
 * ⚠ 여기엔 "PostgREST 응답에 SQLSTATE 가 그대로 오지 않는 경우가 있다" 고 적혀 있었다.
 *   **실측해 보니 틀렸다.** 그대로 온다 —
 *       {"code":"45010","details":"SALE_DATE_OUT_OF_RANGE","hint":null,"message":"…"}
 *   `code` 가 SQLSTATE, `details` 는 서버가 붙인 이름이다(0144). 분기는 SQLSTATE 로
 *   한다 — 그쪽이 PostgreSQL 이 보장하는 값이다.
 */
const codeOf = (e: unknown): string | null => (e instanceof RpcError ? e.code : null);

/** 45001 BEFORE_OPEN — 아직 영업 전. 화면이 시작을 먼저 묻는다. */
export const isNotOpenError = (e: unknown): boolean => codeOf(e) === '45001';

/** 45015 LATE_OPEN — 규칙 종료가 지난 시각의 시작. 오늘 마칠 시간을 골라 다시 연다(0162). */
export const isLateOpenError = (e: unknown): boolean => codeOf(e) === '45015';

/** 45002 DAY_CLOSED — 종료됐거나 자동 마감 기한이 지났다. 되돌릴 길은 없다(§6.4). */
export const isClosedError = (e: unknown): boolean => codeOf(e) === '45002';

/**
 * 서버가 정한 **매장 달력의 오늘**(0125). 발주·입고·재고·레시피 화면이 쓴다.
 *
 * ⚠ 못 받았으면 `null` 이다. **직접 계산해서 메우지 않는다** —
 *   앱이 계산하면 그게 곧 앱과 DB 가 각자 오늘을 계산하는 상태다(기획서 §2.1).
 *   부르는 쪽이 로딩을 다뤄야 한다.
 */
export interface ServerDate {
  /** 서버가 정한 날짜. 아직 못 받았거나 서버가 안 줬으면 `null`. */
  date: string | null;
  isLoading: boolean;
  error: unknown;
  refetch: () => void;
}

/*
 * ⚠ 날짜만 돌려주면 **로딩과 오류를 구별할 수 없다.** 예전엔 `string | null` 이라
 *   RPC 가 실패해도 화면은 "아직 안 왔다" 로 읽고 영원히 로딩만 그렸다.
 *   부르는 쪽이 재시도를 붙일 수 있어야 한다.
 */
export function useStoreLocalDate(): ServerDate {
  const q = useBusinessDay();
  return { date: q.data?.localDate || null, isLoading: q.isLoading, error: q.error, refetch: () => void q.refetch() };
}

/**
 * 서버가 정한 **지금 장부의 날짜**(business_date). 판매 화면이 쓴다.
 *
 * ⚠ 새벽 영업 중이면 **전날**일 수 있다. 그게 이 값의 존재 이유다 —
 *   앱이 자정으로 날짜를 넘겨 버리면 새벽 판매가 다음 날 장부로 샌다.
 */
export function useSalesBusinessDate(): ServerDate {
  const q = useBusinessDay();
  return { date: q.data?.businessDate || null, isLoading: q.isLoading, error: q.error, refetch: () => void q.refetch() };
}

/**
 * 서버가 "낡은 화면"으로 막았는가(45009 · 0117).
 *
 * 다른 기기가 먼저 저장해서 판본이 올라간 경우다. 오류가 아니라 **다음에 할 일**이다 —
 * 다시 받아서 보여 주면 된다. 조용히 덮어쓰면 남이 적은 판매가 사라진다(실측).
 */
export const isRevisionConflict = (e: unknown): boolean => codeOf(e) === '45009';

/** 45010 SALE_DATE_OUT_OF_RANGE — 지난달 1일~오늘 밖이다(0144). */
export const isDateOutOfRange = (e: unknown): boolean => codeOf(e) === '45010';

/** 45011 DAY_IS_LIVE — 그날은 아직 살아 있다. 보통 저장 경로로 가야 한다(0145). */
export const isDayLive = (e: unknown): boolean => codeOf(e) === '45011';

/**
 * '2026-08-20T13:00:00+00:00' → '22:00' — **매장 시간대 기준**(검토 P2-6).
 *
 * ⚠ 예전엔 기기의 getHours() 였다. 뉴욕 매장을 서울 폰으로 보면 종료 22:00 이
 *   11:00 으로 그려졌다 — 시각은 매장 현지가 사실이고, 보는 기기는 우연이다.
 *   시간대는 서버(business_day_state.timezone, 0162)가 준다.
 *   시간대를 못 읽는 기기(Intl 미지원)면 빈 값 — 틀린 시각보다 없는 시각이 낫다.
 */
export function hhmm(iso: string | null, timezone: string): string {
  if (!iso) return '';
  const d = new Date(iso);
  if (Number.isNaN(d.getTime())) return '';
  try {
    const parts = new Intl.DateTimeFormat('en-GB', {
      timeZone: timezone, hour: '2-digit', minute: '2-digit', hour12: false,
    }).formatToParts(d);
    const h = parts.find((p) => p.type === 'hour')?.value ?? '';
    const m = parts.find((p) => p.type === 'minute')?.value ?? '';
    // en-GB 는 자정을 '24'로 낼 수 있다 — 표기는 '00'이다.
    return h === '' || m === '' ? '' : `${h === '24' ? '00' : h}:${m}`;
  } catch {
    return '';
  }
}

/**
 * 판매 입력 카드가 쓰는 **오늘 기준** 메뉴 값(0061).
 *
 * 여기가 마지막으로 남아 있던 구멍이었다. 돈 숫자는 전부 그날 기준으로 고정했는데
 * 판매를 입력하는 카드만 현재 레시피를 보고 있어서, 판매가를 고치면 카드는 새 값을
 * 보여 주고 장부에는 옛 값이 박혔다. 화면이 거짓말을 한 셈이다.
 *
 * 영업 전이면 스냅샷이 없고, 그때는 지금 값이 곧 오늘 값이 된다.
 */
export interface DayMenuBasis {
  recipeId: string;
  name: string;
  /** 오늘 팔면 이 값으로 잡힌다. */
  price: number;
  materialCost: number;
  extraCost: number;
  tax: number;
  fixedCost: number;
  profit: number;
  /** 지금 레시피 값. 달라졌으면 화면이 "내일부터"라고 알린다. */
  currentPrice: number;
  currentMaterialCost: number;
  currentProfit: number;
  changed: boolean;
  /** 오늘 기준에 없는 메뉴 — 오늘 만든 메뉴다. 서버가 판매를 막는다. */
  inBasis: boolean;
  active: boolean;
  blockedBy: string | null;
}

export function useDayMenuBasis(date: string | undefined) {
  const storeId = useStoreId();
  return useQuery({
    queryKey: [...qk.businessDay, 'menus', date ?? ''],
    enabled: Boolean(storeId && date),
    queryFn: async (): Promise<Map<string, DayMenuBasis>> => {
      const { data, error } = await supabase.rpc('day_menu_basis', {
        p_store: storeId, p_date: date as string,
      });
      if (error) throw new Error(error.message);
      const rows = (data ?? []) as unknown as Record<string, unknown>[];
      const m = new Map<string, DayMenuBasis>();
      for (const r of rows) {
        m.set(String(r.recipe_id), {
          recipeId: String(r.recipe_id),
          name: String(r.name ?? ''),
          price: num(r.price),
          materialCost: num(r.material_cost),
          extraCost: num(r.extra_cost),
          tax: num(r.tax),
          fixedCost: num(r.fixed_cost),
          profit: num(r.profit),
          currentPrice: num(r.current_price),
          currentMaterialCost: num(r.current_material_cost),
          currentProfit: num(r.current_profit),
          changed: r.changed === true,
          inBasis: r.in_basis !== false,
          active: r.active !== false,
          blockedBy: str(r.blocked_by),
        });
      }
      return m;
    },
  });
}

/**
 * 수정 내역 — 식재료·레시피가 **같은 원장, 같은 판정**을 쓴다.
 *
 * 기획: docs/식재료-레시피-수정내역-최종기획.md
 *
 * 사장님이 상세에서 세 가지를 바로 알아야 한다.
 *   ① 마지막으로 언제 바뀌었나
 *   ② 내가 고친 건가, 다른 데서 자동으로 반영된 건가
 *   ③ 그 값이 지금 영업의 매출 계산에 들어갔나
 *
 * ⚠ ③은 시간이 지나면 달라진다. 서버가 읽을 때 계산하고 앱은 받아서 그린다 —
 *   앱이 따로 판정하면 두 곳이 어긋난다.
 */
import { useInfiniteQuery, useQuery } from '@tanstack/react-query';
import { qk } from '@/lib/queryClient';
import {
  rpcNullableNumber as numOrNull,
  rpcNullableString as str,
  rpcNumber as num,
} from '@/lib/rpcValue';
import { supabase } from '@/lib/supabase';
import { useStoreId } from '@/lib/SessionProvider';

export type ChangeEntity = 'ingredient' | 'recipe';

/** 서버가 계산한 매출 반영 상태. 화면 문구는 `stateLabel` 이 맡는다. */
export type ChangeState = 'reflected' | 'not_reflected' | 'partial' | 'irrelevant';

export type ChangeSource = 'direct' | 'inbound' | 'ingredient' | 'fixed_cost';

export interface ChangeLine {
  key: string;
  label: string;
  before: string | number | null;
  after: string | number | null;
  unit: string | null;
  /** direct 사장님이 친 값 · derived 그 결과로 계산된 값(0078). */
  kind: 'direct' | 'derived';
}

export interface ChangeEvent {
  id: string | null;
  occurredAt: string;
  title: string;
  /** 목록 한 줄 요약 — `판매가 외 3개 항목 변경`. 서버가 기록할 때 적는다(0078). */
  summary: string;
  sourceType: ChangeSource;
  sourceName: string | null;
  changes: ChangeLine[];
  affectsSales: boolean;
  state: ChangeState;
  /** 같은 변경이 퍼진 다른 메뉴 수. 식재료 카드의 마지막 줄이 된다. */
  affectedRecipes: number;
  /** 아직 한 번도 안 고쳤으면 false — 목록에는 '최초 등록'만 있다. */
  hasHistory: boolean;
}

export function parseChangeEvent(raw: unknown): ChangeEvent {
  const r = (raw ?? {}) as Record<string, unknown>;
  return {
    id: str(r.id),
    occurredAt: String(r.occurred_at ?? ''),
    title: String(r.title ?? ''),
    summary: String(r.summary ?? r.title ?? ''),
    sourceType: (r.source_type ?? 'direct') as ChangeSource,
    sourceName: str(r.source_name),
    changes: ((r.changes ?? []) as Record<string, unknown>[]).map((c) => ({
      key: String(c.key ?? ''),
      label: String(c.label ?? ''),
      before: (c.before ?? null) as string | number | null,
      after: (c.after ?? null) as string | number | null,
      unit: str(c.unit),
      kind: c.change_kind === 'derived' ? 'derived' : 'direct',
    })),
    affectsSales: r.affects_sales === true,
    state: (r.state ?? 'irrelevant') as ChangeState,
    affectedRecipes: num(r.affected_recipes),
    hasHistory: r.has_history !== false,
  };
}

/**
 * 상세 화면 한 줄이 쓰는 마지막 변경(기획 §10).
 *
 * ⚠ 목록의 사건과 **모양이 다르다.** 여기는 시각·상태만 필요하다.
 *   ChangeEvent 로 읽으면 `display_state` 를 못 봐서 상태가 조용히 '무관'이 된다.
 */
export interface LastChange {
  occurredAt: string;
  eventId: string | null;
  /**
   * ⚠ **null 이면 서버가 상태를 말하지 않은 것**이다. 화면은 배지를 그리지 않는다.
   *   'irrelevant' 로 메꾸면 "매출 계산과 무관"이라고 **없는 사실을 주장**하게 된다.
   */
  displayState: ChangeState | null;
  /** 한 번도 안 고쳤으면 false — 그때 occurredAt 은 생성일이다. */
  hasHistory: boolean;
}

const CHANGE_STATES: ChangeState[] = ['reflected', 'not_reflected', 'partial', 'irrelevant'];

/**
 * ⚠ `display_state` 가 빠지면 **개발 중에 바로 터뜨린다.**
 *   조용히 기본값으로 메꾸면 화면이 초록 배지를 달고 아무도 모른다 —
 *   실제로 last_change 모양이 바뀌었을 때 그렇게 새어 나갔다(0078).
 *   배포본에서는 던지지 않는다. 배지 하나 때문에 상세 화면이 통째로 죽으면 안 된다.
 */
export function parseLastChange(raw: unknown): LastChange {
  const r = (raw ?? {}) as Record<string, unknown>;
  const v = r.display_state;

  // ⚠ **키가 없는 것**과 **상태가 null 인 것**은 다르다.
  //   키 없음 = 서버와 파서가 어긋났다(계약 위반) → 개발 중에 터뜨린다.
  //   null    = 한 번도 안 고쳐서 말할 상태가 없다(0082) → 배지를 안 그린다.
  const missing = !('display_state' in r);
  const unknown = v !== null && v !== undefined && !(CHANGE_STATES as string[]).includes(String(v));

  if ((missing || unknown) && __DEV__) {
    throw new Error(
      `last_change.display_state 가 ${missing ? '없습니다' : `모르는 값입니다: ${JSON.stringify(v)}`}. ` +
        '서버 last_entity_change() 와 이 파서가 어긋났습니다.',
    );
  }

  return {
    occurredAt: String(r.occurred_at ?? ''),
    eventId: str(r.event_id),
    displayState: !missing && !unknown && v !== null && v !== undefined ? (v as ChangeState) : null,
    hasHistory: r.has_history === true,
  };
}

/** 기간 창. null 이면 전체 — 좁히면 그 밖의 기록이 닿을 수 없게 되므로 고를 수 있어야 한다. */
export type ChangeWindow = 7 | 30 | null;

export interface ChangeSummary {
  days: number | null;
  count: number;
  directCount: number;
  autoCount: number;
  lastAt: string | null;
  /**
   * 배지를 달 **두 건**의 id — 서버가 정한다(0078).
   * 과거 사건마다 '현재 매출 반영'을 붙이면 현재 값이 여러 개인 것처럼 보인다.
   * 앱이 고르면 식재료 화면과 레시피 화면이 다르게 고를 수 있다.
   */
  latestReflectedId: string | null;
  latestUnreflectedId: string | null;
  latestUnreflectedState: 'not_reflected' | 'partial' | null;
}

/**
 * 목록 한 페이지. 20건씩 받고 커서로 이어 받는다.
 *
 * ⚠ 요약(건수·직접/자동)은 **서버가 창 전체를 세서** 준다. 받은 페이지에서 세면
 *   20건까지만 센 값인데 사장님은 전체라고 읽는다.
 */
export function useChangeHistory(entity: ChangeEntity, id: string | undefined, days: ChangeWindow = 7) {
  const storeId = useStoreId();
  return useInfiniteQuery({
    queryKey: [...qk.changeHistory(entity, id ?? ''), days ?? 'all'],
    enabled: Boolean(storeId && id),
    initialPageParam: null as string | null,
    queryFn: async ({ pageParam }) => {
      const { data, error } = await supabase.rpc('entity_change_history', {
        p_store: storeId,
        p_entity_type: entity,
        p_entity_id: id as string,
        p_cursor: pageParam ?? undefined,
        p_limit: 20,
        p_days: days ?? undefined,
      });
      if (error) throw new Error(error.message);
      const r = (data ?? {}) as unknown as Record<string, unknown>;
      const sm = (r.summary ?? {}) as Record<string, unknown>;
      return {
        items: ((r.items ?? []) as unknown[]).map(parseChangeEvent),
        nextCursor: str(r.next_cursor),
        summary: {
          days: numOrNull(sm.days),
          count: num(sm.count),
          directCount: num(sm.direct_count),
          autoCount: num(sm.auto_count),
          lastAt: str(sm.last_at),
          latestReflectedId: str(sm.latest_reflected_event_id),
          latestUnreflectedId: str(sm.latest_unreflected_event_id),
          latestUnreflectedState: (str(sm.latest_unreflected_state) as
            'not_reflected' | 'partial' | null) ?? null,
        } satisfies ChangeSummary,
      };
    },
    getNextPageParam: (last) => last.nextCursor,
  });
}

/** 상세 화면 헤더에 쓸, 그 항목의 이름. 목록 화면이 부제로 쓴다. */
export function useChangeSubject(entity: ChangeEntity, id: string | undefined) {
  return useQuery({
    queryKey: [...qk.changeHistory(entity, id ?? ''), 'subject'],
    enabled: Boolean(id),
    queryFn: async (): Promise<string> => {
      const table = entity === 'ingredient' ? 'ingredients' : 'recipes';
      const { data, error } = await supabase.from(table).select('name').eq('id', id as string).single();
      if (error) throw new Error(error.message);
      return String((data as { name?: unknown } | null)?.name ?? '');
    },
  });
}

// ── 표기 ──────────────────────────────────────────────────────

/**
 * 매출 반영 상태 문구. 기획 §2 표 그대로다.
 * `일부 메뉴 미반영` 은 식재료 변경이 여러 메뉴에 퍼졌는데 반영 상태가 섞였을 때다.
 */
export function stateLabel(s: ChangeState): { text: string; tone: 'green' | 'amber' | 'neutral' } {
  switch (s) {
    case 'reflected': return { text: '현재 매출 반영', tone: 'green' };
    case 'not_reflected': return { text: '현재 매출 미반영', tone: 'amber' };
    case 'partial': return { text: '일부 메뉴 미반영', tone: 'amber' };
    default: return { text: '매출 계산과 무관', tone: 'neutral' };
  }
}

/**
 * 오늘이면 `방금` · `14:32`, 이전 날짜면 `08.20 14:32`.
 * 기획 §2 의 축약 규칙이다.
 */
export function changeTime(iso: string): string {
  const d = new Date(iso);
  if (Number.isNaN(d.getTime())) return '';
  const now = new Date();
  const hh = String(d.getHours()).padStart(2, '0');
  const mm = String(d.getMinutes()).padStart(2, '0');
  const sameDay =
    d.getFullYear() === now.getFullYear() && d.getMonth() === now.getMonth() && d.getDate() === now.getDate();
  if (sameDay) {
    // 1분 안쪽은 시각보다 '방금'이 읽기 쉽다.
    if (now.getTime() - d.getTime() < 60_000) return '방금';
    return `${hh}:${mm}`;
  }
  return `${String(d.getMonth() + 1).padStart(2, '0')}.${String(d.getDate()).padStart(2, '0')} ${hh}:${mm}`;
}

/** 전후값 한 줄. 숫자는 천단위 구분과 단위를 붙인다. */
export function formatChangeValue(v: string | number | null, unit: string | null): string {
  if (v === null || v === '') return '없음';
  if (typeof v === 'number' || (typeof v === 'string' && v !== '' && !Number.isNaN(Number(v)))) {
    const n = Number(v);
    // 소수점은 의미 있을 때만 — 4.00원/g 처럼 단가는 살리고 12,000원은 정수로.
    const s = Number.isInteger(n) ? n.toLocaleString('ko-KR') : n.toLocaleString('ko-KR', { maximumFractionDigits: 2 });
    return unit ? `${s}${unit}` : s;
  }
  return String(v);
}

// ── 목록 한 줄이 보여 줄 것 ───────────────────────────────────

/**
 * 변경이 어디서 왔는가 — 상세 시트의 부제.
 *
 * ⚠ 화면 문구는 **직접 수정 / 자동 갱신** 둘뿐이다(기획 §2).
 *   '자동 반영'·'자동 전파'·'연관 변경'은 쓰지 않는다.
 */
export function sourceLabel(e: ChangeEvent): string {
  switch (e.sourceType) {
    case 'inbound':
      return e.title === '입고 취소 반영' ? '입고 취소' : '입고 확정';
    case 'ingredient':
      return e.sourceName ? `${e.sourceName} 단가 변경` : '식재료 단가 변경';
    case 'fixed_cost':
      return '고정지출 설정';
    default:
      return '직접 수정';
  }
}

/**
 * 목록에서 이 사건에 배지를 달까. 매출에 영향을 주는 사건은 **최대 두 건**만 단다.
 * 과거 사건마다 '현재 매출 반영'이 붙으면 현재 값이 여러 개인 것처럼 보인다(기획 §5).
 */
export function badgeFor(e: ChangeEvent, s: ChangeSummary | undefined): ChangeState | null {
  // 매출과 무관한 사건은 언제나 그렇게 밝힌다 — 헷갈릴 여지가 없다.
  if (!e.affectsSales) return 'irrelevant';
  if (!s || !e.id) return null;
  if (e.id === s.latestUnreflectedId) return s.latestUnreflectedState ?? 'not_reflected';
  if (e.id === s.latestReflectedId) return 'reflected';
  return null;
}

/** `2026년 8월` — 월 묶음 머리말. */
export function monthLabel(iso: string): string {
  const d = new Date(iso);
  if (Number.isNaN(d.getTime())) return '';
  return `${d.getFullYear()}년 ${d.getMonth() + 1}월`;
}

/** `08/20 · 03:56` — 줄 왼쪽 위 시각. */
export function changeStamp(iso: string): string {
  const d = new Date(iso);
  if (Number.isNaN(d.getTime())) return '';
  const p = (n: number) => String(n).padStart(2, '0');
  return `${p(d.getMonth() + 1)}/${p(d.getDate())} · ${p(d.getHours())}:${p(d.getMinutes())}`;
}

/**
 * 식재료 조회·변경 훅 — 화면과 Supabase 사이의 단일 경계.
 *
 * 화면이 supabase 를 직접 부르지 않게 한다(가이드 P0-1). 그래야
 *   · 쿼리 키가 한 곳에서 관리되고
 *   · 전파 후 무효화 대상이 흩어지지 않으며
 *   · 나중에 조회 방식을 바꿔도 화면을 건드리지 않는다.
 *
 * ⚠ 재고는 DB 에 기준단위(g/ml/개) 총량 하나로 저장한다. 화면은 서버의
 *   `stock_total_base()` 값을 그대로 사용하며 다시 환산하지 않는다(절대원칙 3).
 */
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { invalidate, invalidateOn, qk } from '@/lib/queryClient';
import { supabase } from '@/lib/supabase';
import { useStoreId } from '@/lib/SessionProvider';
import { parseLastChange, type LastChange } from '@/features/changes/hooks';
import { asJson } from '@/lib/json';
import {
  rpcNullableNumber as numOrNull,
  rpcNullableString as str,
  rpcNumber as num,
} from '@/lib/rpcValue';

export type BaseUnit = 'g' | 'ml' | 'ea';

/** 목록 카드가 필요한 만큼만. 화면이 쓰지 않는 컬럼까지 끌어오지 않는다. */
export interface IngredientRow {
  id: string;
  name: string;
  categoryName: string | null;
  baseUnit: BaseUnit;
  perVolume: number;
  safetyStock: number;
  vendorName: string | null;
  memo: string | null;
  /** 재고 총량(기준단위) — 서버 `stock_total_base()` 값 */
  stockTotal: number;
  /** 기준단가(원/기준단위). 구매 이력이 없거나 로스율이 100% 이상이면 null(산출 불가). */
  basePrice: number | null;
  soonOut: boolean;
  lastInboundAt: string | null;
}

export interface PurchaseOption {
  id: string;
  url: string | null;
  name: string;
  volume: number;
  amount: number;
  vendorId: string | null;
  vendorName: string | null;
  /**
   * 제조사·브랜드(0084). **아직 입력 화면이 없어 항상 null 이다** —
   * brands 테이블도 비어 있다. 값이 생기면 목록 첫 줄이 바로 받는다.
   */
  brandId: string | null;
  brandName: string | null;
}

/**
 * 빠른 입고 미리보기(0074) — **서버가 낸다.**
 *
 * ⚠ 앱이 따로 계산하면 확정 후 숫자와 갈린다. 4.81 을 보고 눌렀는데 4.85 가 되면
 *   사장님은 그 화면을 두 번 다시 안 믿는다.
 */
export interface QuickInboundPreview {
  stockBefore: number;
  stockAfter: number;
  added: number;
  paid: number;
  inboundUnitPrice: number | null;
  basePriceBefore: number | null;
  basePriceAfter: number | null;
  affectedRecipes: number;
}

export function useQuickInboundPreview(
  ingredientId: string | undefined, volume: number, amount: number, qty: number,
) {
  const storeId = useStoreId();
  return useQuery({
    queryKey: [...qk.ingredient(ingredientId ?? ''), 'quick-preview', volume, amount, qty],
    enabled: Boolean(storeId && ingredientId && volume > 0 && qty > 0),
    queryFn: async (): Promise<QuickInboundPreview> => {
      const { data, error } = await supabase.rpc('quick_inbound_preview', {
        p_store: storeId, p_ingredient: ingredientId as string,
        p_volume: volume, p_amount: amount, p_qty: qty,
      });
      if (error) throw new Error(error.message);
      const r = (data ?? {}) as unknown as Record<string, unknown>;
      return {
        stockBefore: num(r.stock_before),
        stockAfter: num(r.stock_after),
        added: num(r.added),
        paid: num(r.paid),
        inboundUnitPrice: numOrNull(r.inbound_unit_price),
        basePriceBefore: numOrNull(r.base_price_before),
        basePriceAfter: numOrNull(r.base_price_after),
        affectedRecipes: num(r.affected_recipes),
      };
    },
  });
}

export interface QuickInboundInput {
  ingredientId: string;
  /** 팩 1개 용량(기준단위) */
  volume: number;
  /** 팩 1개 금액 — 실제 결제금액 ÷ 개수 */
  amount: number;
  qty: number;
  vendorId?: string | null;
  occurredAt?: string;
  /** 두 번 눌러도 한 번만 들어가게 하는 키(0074). */
  idempotencyKey?: string;
}

/**
 * 발주 없이 산 것을 바로 넣는다. **한 RPC** 다 — e7 → e1 을 앱에서 두 번 부르면
 * 중간에 끊겼을 때 유령 발주가 남고 사장님은 정리할 방법이 없다.
 */
export function useQuickInbound() {
  const qc = useQueryClient();
  const storeId = useStoreId();
  return useMutation({
    mutationFn: async (input: QuickInboundInput): Promise<void> => {
      const { error } = await supabase.rpc('quick_inbound', {
        p_store: storeId,
        p_ingredient: input.ingredientId,
        p_volume: input.volume,
        p_amount: input.amount,
        p_qty: input.qty,
        p_vendor: input.vendorId ?? undefined,
        p_occurred_at: input.occurredAt,
        p_idempotency_key: input.idempotencyKey,
      });
      if (error) throw new Error(error.message);
    },
    // 입고는 단가를 바꾼다 — 그 재료뿐 아니라 **전 레시피**와 매출 원가가 함께 움직인다.
    onSuccess: (_r, input) => invalidate(qc, invalidateOn.e1(input.ingredientId)),
  });
}

/** 상세 화면의 '구매 이력' — 발주 기록 최근 20건. */
export interface PurchaseRecord {
  id: string;
  orderedAt: string;
  status: 'ordered' | 'partial' | 'received' | 'canceled';
  volume: number;
  amount: number;
  qty: number;
  receivedQty: number;
  vendorName: string | null;
  unitPrice: number | null;
}

export interface IngredientDetail extends IngredientRow {
  /**
   * 상세 첫 카드 아래 한 줄에 쓸 마지막 변경(0063).
   *
   * ⚠ **목록 타입에 두면 안 된다.** `toRow` 는 목록·상세가 함께 쓰는데
   *   `ingredient_list` 는 `last_change` 를 주지 않는다. 거기서 파서를 부르면
   *   목록이 통째로 터진다 — 실제로 그렇게 났다.
   */
  lastChange: LastChange;
  categoryId: string | null;
  defaultVendorId: string | null;
  minOrderQty: number;
  purchase: { avg: number | null; low: number | null; high: number | null; count: number };
  priceTrends: { date: string; price: number }[];
  options: PurchaseOption[];
  orders: PurchaseRecord[];
  loss: IngredientLoss;
}

export interface LedgerEntry {
  id: string;
  date: string;
  type: 'inbound' | 'consume' | 'discard' | 'stocktake' | 'adjust';
  /** 재고 증감 — **기준단위**. 종류와 무관하게 같은 단위다(0034). */
  countDelta: number;
  volumeDelta: number | null;
  note: string | null;
  /** 그 사건 직후 잔량. 서버가 누적해서 준다 — 앱이 종류별 분기를 알 필요가 없다. */
  balance: number;
  /** 이미 되돌려진 폐기인가. 되돌린 폐기는 로스율 표시에서 빠진다. */
  reverted: boolean;
  /** 조리 폐기(메뉴를 만들어 놓고 못 팔아 버린 몫)인가. 보관 폐기와 원인이 다르다(0041). */
  waste: boolean;
}

/**
 * 실측 로스율 — **표시 전용**(0042). 기준단가에 곱하지 않는다.
 * 보관 폐기와 조리 폐기를 갈라서 준다. 원인이 다르면 사장님이 할 일도 다르다.
 * 폐기 기록이 없으면 rate 는 null — 0% 로 단정하지 않는다.
 */
export interface IngredientLoss {
  purchased: number;
  storageAmount: number;
  cookingAmount: number;
  storageCount: number;
  cookingCount: number;
  totalAmount: number;
  totalCost: number | null;
  rate: number | null;
  storageRate: number | null;
  cookingRate: number | null;
}

function toRow(r: Record<string, unknown>): IngredientRow {
  return {
    id: String(r.id),
    name: String(r.name),
    categoryName: str(r.category_name),
    baseUnit: r.base_unit as BaseUnit,
    perVolume: num(r.per_volume),
    safetyStock: num(r.safety_stock),
    vendorName: str(r.vendor_name),
    memo: str(r.memo),
    stockTotal: num(r.stock_total),
    basePrice: numOrNull(r.base_price),
    soonOut: Boolean(r.soon_out),
    lastInboundAt: str(r.last_inbound_at),
  };
}

/**
 * 목록 조회.
 *
 * 재고 총량·기준단가는 **서버 함수**라 일반 select 로는 못 가져온다.
 * 한 건씩 RPC 를 부르면 N+1 이 되므로 목록 전용 함수를 쓴다.
 */
export function useIngredientList() {
  const storeId = useStoreId();
  return useQuery({
    queryKey: qk.ingredients,
    queryFn: async (): Promise<IngredientRow[]> => {
      const { data, error } = await supabase.rpc('ingredient_list', { p_store: storeId });
      if (error) throw new Error(error.message);
      return ((data ?? []) as Record<string, unknown>[]).map(toRow);
    },
  });
}

/** 상세 (ING-03) — 구매 이력 요약·단가 추이·구매 옵션까지 한 번에. */
export function useIngredientDetail(id: string | undefined) {
  return useQuery({
    queryKey: qk.ingredient(id ?? ''),
    enabled: Boolean(id),
    queryFn: async (): Promise<IngredientDetail | null> => {
      const { data, error } = await supabase.rpc('ingredient_detail', { p_ingredient: id as string });
      if (error) throw new Error(error.message);
      if (!data) return null;
      const r = data as unknown as Record<string, unknown>;
      const pu = (r.purchase ?? {}) as Record<string, unknown>;
      return {
        ...toRow(r),
        lastChange: parseLastChange(r.last_change),
        categoryId: str(r.category_id),
        defaultVendorId: str(r.default_vendor_id),
        minOrderQty: num(r.min_order_qty),
        loss: (() => {
          const l = (r.loss ?? {}) as Record<string, unknown>;
          return {
            purchased: num(l.purchased),
            storageAmount: num(l.storage_amount),
            cookingAmount: num(l.cooking_amount),
            storageCount: num(l.storage_count),
            cookingCount: num(l.cooking_count),
            totalAmount: num(l.total_amount),
            totalCost: numOrNull(l.total_cost),
            rate: numOrNull(l.rate),
            storageRate: numOrNull(l.storage_rate),
            cookingRate: numOrNull(l.cooking_rate),
          };
        })(),
        purchase: {
          avg: numOrNull(pu.avg),
          low: numOrNull(pu.low),
          high: numOrNull(pu.high),
          count: num(pu.count),
        },
        priceTrends: ((r.price_trends ?? []) as Record<string, unknown>[]).map((t) => ({
          date: String(t.date),
          price: num(t.price),
        })),
        options: ((r.options ?? []) as Record<string, unknown>[]).map((o) => ({
          id: String(o.id),
          url: str(o.url),
          name: String(o.name),
          volume: num(o.volume),
          amount: num(o.amount),
          vendorId: str(o.vendor_id),
          vendorName: str(o.vendor_name),
          brandId: str(o.brand_id),
          brandName: str(o.brand_name),
        })),
        orders: ((r.orders ?? []) as Record<string, unknown>[]).map((o) => ({
          id: String(o.id),
          orderedAt: String(o.ordered_at),
          status: o.status as PurchaseRecord['status'],
          volume: num(o.volume),
          amount: num(o.amount),
          qty: num(o.qty),
          receivedQty: num(o.received_qty),
          vendorName: str(o.vendor_name),
          unitPrice: numOrNull(o.unit_price),
        })),
      };
    },
  });
}

/** 재고 변동 원장 (ING-07). */
/** 구매 이력 한 건 — 그날 그 값이다. 기준단가(가중평균)와 다르다. */
export interface PurchaseRow {
  id: string;
  orderedAt: string;
  expectedAt: string | null;
  status: 'ordered' | 'partial' | 'received' | 'canceled';
  vendorName: string | null;
  volume: number;
  amount: number;
  qty: number;
  receivedQty: number | null;
  unitPrice: number | null;
}

/**
 * 구매 이력 전체 — ingredient_detail 은 20건으로 자르므로 전체 보기는 이쪽을 쓴다.
 * 단가가 언제부터 올랐는지 보려면 잘리지 않은 목록이 필요하다.
 */
export function usePurchaseHistory(id: string | undefined, range?: { from?: string; to?: string }) {
  return useQuery({
    queryKey: [...qk.purchaseHistory(id ?? ''), range?.from ?? '', range?.to ?? ''],
    enabled: Boolean(id),
    queryFn: async (): Promise<PurchaseRow[]> => {
      const { data, error } = await supabase.rpc('purchase_history', {
        p_ingredient: id as string,
        p_from: range?.from,
        p_to: range?.to,
      });
      if (error) throw new Error(error.message);
      return ((data ?? []) as Record<string, unknown>[]).map((r) => ({
        id: String(r.id),
        orderedAt: String(r.ordered_at),
        expectedAt: str(r.expected_at),
        status: r.status as PurchaseRow['status'],
        vendorName: str(r.vendor_name),
        volume: num(r.volume),
        amount: num(r.amount),
        qty: num(r.qty),
        receivedQty: numOrNull(r.received_qty),
        unitPrice: numOrNull(r.unit_price),
      }));
    },
  });
}

export function useStockHistory(id: string | undefined, range?: { from?: string; to?: string }) {
  return useQuery({
    queryKey: [...qk.stockHistory(id ?? ''), range?.from ?? '', range?.to ?? ''],
    enabled: Boolean(id),
    queryFn: async (): Promise<LedgerEntry[]> => {
      const { data, error } = await supabase.rpc('stock_history', {
        p_ingredient: id as string,
        p_from: range?.from,
        p_to: range?.to,
      });
      if (error) throw new Error(error.message);
      return ((data ?? []) as Record<string, unknown>[]).map((e) => ({
        id: String(e.id),
        date: String(e.occurred_on),
        type: e.type as LedgerEntry['type'],
        countDelta: num(e.count_delta),
        volumeDelta: numOrNull(e.volume_delta),
        note: str(e.note),
        balance: num(e.balance),
        reverted: Boolean(e.reverted),
        waste: Boolean(e.waste),
      }));
    },
  });
}

export interface IngredientInput {
  id?: string;
  name: string;
  categoryId: string | null;
  baseUnit: BaseUnit;
  perVolume: number;
  safetyStock: number;
  minOrderQty: number;
  defaultVendorId: string | null;
  memo: string | null;
}

/** 등록·수정 (ING-02 / ING-04). 저장 한 번이 서버 트랜잭션 하나다. */
export function useSaveIngredient() {
  const qc = useQueryClient();
  const storeId = useStoreId();
  return useMutation({
    mutationFn: async (input: IngredientInput): Promise<string> => {
      const { data, error } = await supabase.rpc('save_ingredient', {
        p_store: storeId,
        p_payload: asJson({
          id: input.id ?? '',
          name: input.name,
          category_id: input.categoryId ?? '',
          base_unit: input.baseUnit,
          per_volume: input.perVolume,
          safety_stock: input.safetyStock,
          min_order_qty: input.minOrderQty,
          default_vendor_id: input.defaultVendorId ?? '',
          memo: input.memo ?? '',
        }),
      });
      if (error) throw new Error(error.message);
      return String(data);
    },
    onSuccess: (id) => invalidate(qc, invalidateOn.ingredientSaved(id)),
  });
}

/** 삭제 = 비활성화. 과거 입고·판매 기록은 그대로 남는다(원장 보존). */
export function useDeactivateIngredient() {
  const qc = useQueryClient();
  return useMutation({
    mutationFn: async (id: string) => {
      const { error } = await supabase.rpc('deactivate_ingredient', { p_ingredient: id });
      if (error) throw new Error(error.message);
    },
    onSuccess: () => invalidate(qc, invalidateOn.ingredientSaved()),
  });
}

export interface PurchaseOptionInput {
  id?: string;
  ingredientId: string;
  name: string;
  vendorId: string | null;
  volume: number;
  amount: number;
  url: string | null;
}

/** 구매 옵션 등록·수정 (ING-05). */
export function useSavePurchaseOption() {
  const qc = useQueryClient();
  const storeId = useStoreId();
  return useMutation({
    mutationFn: async (input: PurchaseOptionInput) => {
      const { error } = await supabase.rpc('save_purchase_option', {
        p_store: storeId,
        p_payload: asJson({
          id: input.id ?? '',
          ingredient_id: input.ingredientId,
          purchase_name: input.name,
          vendor_id: input.vendorId ?? '',
          volume: input.volume,
          amount: input.amount,
          url: input.url ?? '',
        }),
      });
      if (error) throw new Error(error.message);
    },
    onSuccess: (_r, input) => invalidate(qc, [qk.ingredient(input.ingredientId)]),
  });
}

/**
 * 폐기 삭제 (E2 상쇄) — 최근 7일치만(0086).
 *
 * 원장은 지우지 않고 반대 이벤트를 쌓는다. 재고는 돌아오고 로스율에서도 빠진다.
 * ⚠ 기간 제한은 **서버가** 막는다. 화면이 ⋮ 를 감추는 건 안내일 뿐이다.
 */
export function useDeleteDiscard(ingredientId: string) {
  const qc = useQueryClient();
  return useMutation({
    mutationFn: async (input: { eventId: string; reason?: string }) => {
      const { data, error } = await supabase.rpc('e2_discard_reverted', {
        p_event: input.eventId,
        p_reason: input.reason,
      });
      if (error) throw new Error(error.message);
      const r = (data ?? {}) as unknown as Record<string, unknown>;
      return { alreadyReverted: Boolean(r.already_reverted), restored: num(r.restored) };
    },
    onSuccess: () => invalidate(qc, invalidateOn.e2(ingredientId)),
  });
}

/** 폐기를 지울 수 있는 기간(일). SQL discard_delete_days() 와 같은 값이어야 한다. */
export const DISCARD_DELETE_DAYS = 7;

export function useDeletePurchaseOption(ingredientId: string) {
  const qc = useQueryClient();
  return useMutation({
    mutationFn: async (id: string) => {
      const { error } = await supabase.rpc('delete_purchase_option', { p_id: id });
      if (error) throw new Error(error.message);
    },
    onSuccess: () => invalidate(qc, [qk.ingredient(ingredientId)]),
  });
}

/** 폐기 결과 — 버릴 게 없으면 서버가 아무 일도 하지 않고 skipped 로 알린다. */
export interface DiscardResult {
  discarded: number;
  skipped: boolean;
  unitPrice: number | null;
}

/**
 * 재고 수정 — 조정(E5) / 완전 소진(E5) / 폐기(E2).
 *
 * 어떤 종류인지에 따라 **다른 RPC** 를 부른다. 폐기는 실측 로스율에 누적되어 기준단가까지
 * 바꾸므로 조정으로 기록하면 로스율이 영원히 0 이 된다.
 */
export function useStockChange() {
  const qc = useQueryClient();
  return useMutation({
    mutationFn: async (input: {
      ingredientId: string;
      kind: 'adj' | 'out' | 'waste';
      /** 조정·소진: 변경 후 총량(기준단위). 폐기: 남은 양(기준단위). */
      value: number;
      soonOut?: boolean;
      /** 원장에 남길 사유. 비워두면 서버가 기본 문구를 쓴다. */
      reason?: string;
    }) => {
      if (input.kind === 'waste') {
        // E2 는 "남은 양"을 받아 폐기량을 역산한다.
        const { data, error } = await supabase.rpc('e2_discard', {
          p_ingredient: input.ingredientId,
          p_remain_volume: input.value,
        });
        if (error) throw new Error(error.message);
        const r = (data ?? {}) as unknown as Record<string, unknown>;
        return {
          discarded: num(r.discarded),
          skipped: Boolean(r.skipped),
          unitPrice: numOrNull(r.unit_price),
        } satisfies DiscardResult;
      }
      const target = input.kind === 'out' ? 0 : input.value;
      const { error } = await supabase.rpc('e5_stock_adjusted', {
        p_ingredient: input.ingredientId,
        p_stock_total: target,
        p_soon: input.kind === 'out' ? true : Boolean(input.soonOut),
        p_note: input.reason,
      });
      if (error) throw new Error(error.message);
    },
    onSuccess: (_r, input) =>
      invalidate(qc, input.kind === 'waste' ? invalidateOn.e2(input.ingredientId) : invalidateOn.e5(input.ingredientId)),
  });
}

/**
 * 카테고리·거래처·판매 채널·부자재의 공용 마스터 데이터 훅.
 * 화면 도메인과 무관한 기준 목록과 생명주기를 이 경계에서 소유한다.
 */
import { useCallback } from 'react';
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { invalidate, invalidateOn, qk } from '@/lib/queryClient';
import { supabase } from '@/lib/supabase';
import { asJson } from '@/lib/json';
import { useStoreId } from '@/lib/SessionProvider';
import { rpcNullableString as str, rpcNumber as num } from '@/lib/rpcValue';

export type CategoryKind = 'ingredient' | 'recipe' | 'material';

export interface CategoryRow { id: string; name: string; kind: CategoryKind; sortOrder: number; usedCount: number }
export interface VendorRow { id: string; name: string; usedCount: number }
export interface ChannelRow { id: string; code: string; name: string; active: boolean }
/** 부자재 마스터 — 여러 메뉴가 같은 단가를 참조하게 한다. */
export interface MaterialRow {
  id: string;
  name: string;
  categoryId: string | null;
  categoryName: string | null;
  unitCost: number;
  unitLabel: string;
  memo: string | null;
  usedCount: number;
}

export interface SettingsLists {
  categories: CategoryRow[];
  recipeCategories: CategoryRow[];
  materialCategories: CategoryRow[];
  materials: MaterialRow[];
  vendors: VendorRow[];
  channels: ChannelRow[];
}

export function useSettingsLists() {
  const storeId = useStoreId();
  return useQuery({
    queryKey: qk.settingsLists,
    queryFn: async (): Promise<SettingsLists> => {
      const { data, error } = await supabase.rpc('settings_lists', { p_store: storeId });
      if (error) throw new Error(error.message);
      const r = (data ?? {}) as unknown as Record<string, unknown>;
      const cats = (v: unknown): CategoryRow[] =>
        ((v ?? []) as Record<string, unknown>[]).map((c) => ({
          id: String(c.id), name: String(c.name),
          kind: (c.kind as CategoryKind) ?? 'ingredient',
          sortOrder: num(c.sort_order),
          usedCount: num(c.used_count),
        }));

      return {
        categories: cats(r.categories),
        recipeCategories: cats(r.recipe_categories),
        materialCategories: cats(r.material_categories),
        materials: ((r.materials ?? []) as Record<string, unknown>[]).map((m) => ({
          id: String(m.id), name: String(m.name),
          categoryId: str(m.category_id), categoryName: str(m.category_name),
          unitCost: num(m.unit_cost), unitLabel: String(m.unit_label ?? '개'),
          memo: str(m.memo), usedCount: num(m.used_count),
        })),
        vendors: ((r.vendors ?? []) as Record<string, unknown>[]).map((v) => ({
          id: String(v.id), name: String(v.name), usedCount: num(v.used_count),
        })),
        channels: ((r.channels ?? []) as Record<string, unknown>[]).map((c) => ({
          id: String(c.id), code: String(c.code), name: String(c.name),
          active: Boolean(c.active),
        })),
      };
    },
  });
}

