/**
 * MY가 소유하는 고정 지출·매장명·매출 검산 훅.
 * 공용 설정과 마스터 데이터는 각각 features/settings, features/master-data가 소유한다.
 */
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { invalidate, invalidateOn, qk } from '@/lib/queryClient';
import { supabase } from '@/lib/supabase';
import { asJson } from '@/lib/json';
import { useStoreId } from '@/lib/SessionProvider';
import { rpcNumber as num } from '@/lib/rpcValue';

// ── 고정지출 (MY-05) ──────────────────────────────────────────
export interface FixedCostLine { name: string; amount: number }
/** 채널 코드 -> 비중(%). null 이면 채널 매출 비중으로 자동 배분한다. */
export type ChannelWeights = Record<string, number>;
export interface FixedCostItem {
  key: string;
  mode: 'total' | 'detail';
  total: number;
  lines: FixedCostLine[];
  weights: ChannelWeights | null;
}
export interface FixedCosts {
  month: string;
  totalRevenue: number;
  items: FixedCostItem[];
  /** 고정지출률 = 합계 ÷ 월 매출. 서버 `fixed_cost_rate()` 와 같은 정의. */
  rate: number | null;
}

/**
 * ⚠ `month` 에 기본값을 **두지 않는다**(0126). 예전엔 core 의 `currentBusinessMonth`
 *   였는데, 그건 기기 시계에서 나온 `+09:00` 고정 오프셋 값이다. 뉴욕 매장의
 *   8/31 22:00 은 서울로 9/1 이라 **서버는 8월 장부를 보는데 이 훅만 9월을 열었다.**
 *   부르는 쪽이 서버 월(`localDate.slice(0, 7)`)을 넘긴다.
 */
export function useFixedCosts(month: string) {
  const storeId = useStoreId();
  return useQuery({
    queryKey: qk.fixedCosts(month),
    queryFn: async (): Promise<FixedCosts> => {
      const { data, error } = await supabase
        .from('fixed_costs_monthly')
        .select('month, total_revenue, items')
        .eq('store_id', storeId)
        .eq('month', month)
        .maybeSingle();
      if (error) throw new Error(error.message);

      const items = ((data?.items ?? []) as unknown as Record<string, unknown>[]).map((i) => ({
        key: String(i.key),
        mode: (i.mode as 'total' | 'detail') ?? 'total',
        total: num(i.total),
        lines: ((i.lines ?? []) as Record<string, unknown>[]).map((l) => ({
          name: String(l.name ?? ''), amount: num(l.amount),
        })),
        weights: i.weights && typeof i.weights === 'object'
          ? Object.fromEntries(Object.entries(i.weights as Record<string, unknown>).map(([k, v]) => [k, num(v)]))
          : null,
      }));
      const revenue = num(data?.total_revenue);
      const sum = items.reduce((a, i) => a + i.total, 0);
      return { month, totalRevenue: revenue, items, rate: revenue > 0 ? sum / revenue : null };
    },
  });
}

export function useSaveFixedCosts() {
  const qc = useQueryClient();
  const storeId = useStoreId();
  return useMutation({
    mutationFn: async (input: { month: string; totalRevenue: number; items: FixedCostItem[] }) => {
      const { error } = await supabase.rpc('save_fixed_costs', {
        p_store: storeId,
        p_month: input.month,
        p_total_revenue: input.totalRevenue,
        // 합계 정규화는 서버가 한다(줄이 있으면 줄의 합이 진실). 여기서 또 계산하면 두 벌이 된다.
        p_items: asJson(input.items.map((i) => ({
          key: i.key,
          mode: i.mode,
          total: i.total,
          lines: i.lines,
          ...(i.weights ? { weights: i.weights } : {}),
        }))),
      });
      if (error) throw new Error(error.message);
    },
    onSuccess: (_r, input) => invalidate(qc, [...invalidateOn.e4(), qk.fixedCosts(input.month)]),
  });
}


/** 매장 이름 — 마이페이지 헤더에 쓴다. 하드코딩하면 다른 매장에서 남의 상호가 보인다. */
export function useStoreName() {
  const storeId = useStoreId();
  return useQuery({
    queryKey: [...qk.store, 'name'],
    queryFn: async (): Promise<string | null> => {
      const { data, error } = await supabase.from('stores').select('name').eq('id', storeId).maybeSingle();
      if (error) throw new Error(error.message);
      return data?.name ?? null;
    },
  });
}

/** 채널별 고정지출 배분 (SALES-18). 항목 비중이 있으면 그대로, 없으면 매출 비중. */
export function useChannelFixed(from: string, to: string, enabled = true) {
  const storeId = useStoreId();
  return useQuery({
    queryKey: [...qk.salesRange(from, to), 'channel-fixed'],
    enabled: enabled && Boolean(from) && Boolean(to),
    queryFn: async (): Promise<{ total: number; provisional: boolean; byChannel: Record<string, number> }> => {
      const { data, error } = await supabase.rpc('sales_channel_fixed', { p_store: storeId, p_from: from, p_to: to });
      if (error) throw new Error(error.message);
      const r = (data ?? {}) as unknown as Record<string, unknown>;
      const ch = (r.channels ?? {}) as Record<string, unknown>;
      return {
        total: num(r.total),
        provisional: Boolean(r.provisional),
        byChannel: Object.fromEntries(Object.entries(ch).map(([k, v]) => [k, num(v)])),
      };
    },
  });
}

/**
 * 수기 월매출(고정지출률 분모)과 실제 매출의 괴리 (M-030).
 *
 * 총 월매출은 수기 입력이 설계 의도다(레시피 v3 §111). 그래서 자동으로 덮어쓰지 않고
 * **얼마나 어긋났는지만** 보여준다. 그 숫자가 전 메뉴 순이익에 곱해지므로,
 * 어긋난 걸 모르면 모든 메뉴 손익이 조용히 틀어진다.
 */
export interface RevenueCheck {
  month: string;
  daysElapsed: number;
  daysTotal: number;
  /** 진행 중인 달이면 true — 월 환산이 추정치임을 화면이 밝혀야 한다. */
  inProgress: boolean;
  /** 사장님이 적은 값. 안 적었으면 null(0원 매출과 구분한다). */
  manualRevenue: number | null;
  fixedTotal: number | null;
  actualRevenue: number;
  /** 진행 중인 달은 일할 환산, 끝난 달은 실적 그대로. 경과 0일이면 null. */
  projectedRevenue: number | null;
  /** (월 환산 ÷ 수기) − 1, %. 둘 중 하나라도 없으면 null. */
  gapPct: number | null;
  rateManual: number | null;
  rateProjected: number | null;
  hasSales: boolean;
}

/** ⚠ 기본값 없음 — 위 `useFixedCosts` 와 같은 이유다(0126). */
export function useRevenueCheck(month: string) {
  const storeId = useStoreId();
  return useQuery({
    queryKey: [...qk.fixedCosts(month), 'revenue-check'],
    queryFn: async (): Promise<RevenueCheck> => {
      const { data, error } = await supabase.rpc('fixed_cost_revenue_check', {
        p_store: storeId,
        p_month: month,
      });
      if (error) throw new Error(error.message);
      const r = (data ?? {}) as unknown as Record<string, unknown>;
      return {
        month: String(r.month ?? month),
        daysElapsed: num(r.days_elapsed),
        daysTotal: num(r.days_total),
        inProgress: Boolean(r.in_progress),
        manualRevenue: r.manual_revenue == null ? null : num(r.manual_revenue),
        fixedTotal: r.fixed_total == null ? null : num(r.fixed_total),
        actualRevenue: num(r.actual_revenue),
        projectedRevenue: r.projected_revenue == null ? null : num(r.projected_revenue),
        gapPct: r.gap_pct == null ? null : num(r.gap_pct),
        rateManual: r.rate_manual == null ? null : num(r.rate_manual),
        rateProjected: r.rate_projected == null ? null : num(r.rate_projected),
        hasSales: Boolean(r.has_sales),
      };
    },
  });
}

/**
 * 발주 조회·등록 훅.
 *
 * ⚠ 절대원칙 2: 발주 등록(E7)은 **기록만** 한다. 재고·기준단가는 변하지 않는다.
 *   실제 재고 반영은 입고 확정(E1)에서만 일어난다. 그래서 무효화 대상도 다르다.
 */
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { invalidate, invalidateOn, qk } from '@/lib/queryClient';
import {
  rpcNullableNumber as numOrNull,
  rpcNullableString as str,
  rpcNumber as num,
} from '@/lib/rpcValue';
import { supabase, makeInboundKey } from '@/lib/supabase';
import { useStoreId } from '@/lib/SessionProvider';

export type CandidateReason = 'safety_stock' | 'soon_out' | 'manual';

const normalizeReasons = (reasons: unknown): CandidateReason[] => {
  const raw = Array.isArray(reasons) ? reasons : [];
  return raw.filter(
    (r): r is CandidateReason => r === 'safety_stock' || r === 'soon_out' || r === 'manual',
  );
};

export interface OrderCandidate {
  ingredientId: string;
  name: string;
  reasons: CandidateReason[];
  recommendedQty: number;
  status: 'pending' | 'ordered' | 'excluded';
  stockTotal: number;
  safetyTotal: number;
  baseUnit: 'g' | 'ml' | 'ea';
  perVolume: number;
}

export interface OrderRecord {
  id: string;
  ingredientId: string;
  name: string;
  vendorName: string | null;
  volume: number;
  amount: number;
  qty: number;
  receivedQty: number;
  status: 'ordered' | 'partial' | 'received' | 'canceled';
  orderedAt: string;
  expectedAt: string | null;
  unitPrice: number | null;
}

export interface OrderBoard {
  candidates: OrderCandidate[];
  waiting: OrderRecord[];
  received: OrderRecord[];
}

const toRecord = (r: Record<string, unknown>): OrderRecord => ({
  id: String(r.id),
  ingredientId: String(r.ingredient_id),
  name: String(r.name),
  vendorName: str(r.vendor_name),
  volume: num(r.volume),
  amount: num(r.amount),
  qty: num(r.qty),
  receivedQty: num(r.received_qty),
  status: (r.status as OrderRecord['status']) ?? 'received',
  orderedAt: String(r.ordered_at),
  expectedAt: str(r.expected_at),
  unitPrice: numOrNull(r.unit_price),
});

/** 발주 현황 3탭(후보·입고대기·입고완료)을 한 번에. */
export function useOrderBoard() {
  const storeId = useStoreId();
  return useQuery({
    queryKey: qk.orders,
    queryFn: async (): Promise<OrderBoard> => {
      const { data, error } = await supabase.rpc('order_board', { p_store: storeId });
      if (error) throw new Error(error.message);
      const r = (data ?? {}) as unknown as Record<string, unknown>;
      return {
        candidates: ((r.candidates ?? []) as Record<string, unknown>[]).map((c) => ({
          ingredientId: String(c.ingredient_id),
          name: String(c.name),
          reasons: normalizeReasons(c.reasons),
          recommendedQty: num(c.recommended_qty),
          status: (c.status as OrderCandidate['status']) ?? 'pending',
          stockTotal: num(c.stock_total),
          safetyTotal: num(c.safety_total),
          baseUnit: c.base_unit as OrderCandidate['baseUnit'],
          perVolume: num(c.per_volume),
        })),
        waiting: ((r.waiting ?? []) as Record<string, unknown>[]).map(toRecord),
        received: ((r.received ?? []) as Record<string, unknown>[]).map(toRecord),
      };
    },
  });
}

export interface PlaceOrderInput {
  ingredientId: string;
  vendorId: string | null;
  volume: number;
  amount: number;
  qty: number;
  /** 도착 예정일 'YYYY-MM-DD' */
  expectedAt: string;
}

/** E7 발주 등록 — 여러 건을 한 번에 보낼 수 있다(발주서 화면). */
export function usePlaceOrders() {
  const qc = useQueryClient();
  const storeId = useStoreId();
  return useMutation({
    mutationFn: async (items: PlaceOrderInput[]): Promise<string[]> => {
      const ids: string[] = [];
      for (const it of items) {
        const { data, error } = await supabase.rpc('e7_place_order', {
          p_store: storeId,
          p_ingredient: it.ingredientId,
          p_vendor: (it.vendorId ?? null) as string,
          p_brand: null as unknown as string,
          p_volume: it.volume,
          p_amount: it.amount,
          p_qty: it.qty,
          p_expected: it.expectedAt,
          p_source: 'manual',
        });
        if (error) throw new Error(error.message);
        ids.push(String(data));
      }
      return ids;
    },
    onSuccess: () => invalidate(qc, invalidateOn.e7()),
  });
}

export interface ConfirmInboundResult {
  orderId: string;
  receivedQty: number;
  unitPrice: number | null;
  /** 직전 평균 대비 급등 여부 — 화면이 경고를 띄운다. */
  priceSpike: boolean;
  duplicate: boolean;
  alreadyReceived: boolean;
}

/**
 * E1 입고 확정.
 *
 * `idempotencyKey` 는 **사용자 의도 1회분**을 식별한다. 화면은 버튼을 누른 시점에 키를 한 번
 * 만들어 두고 재시도에는 같은 값을 다시 넘겨야 중복 입고가 막힌다. 방어는 DB 유니크 인덱스가
 * 하므로 debounce 에 의존하지 않는다.
 */
export function useConfirmInbound() {
  const qc = useQueryClient();
  return useMutation({
    mutationFn: async (input: {
      orderId: string;
      ingredientId: string;
      actualQty?: number;
      idempotencyKey?: string;
      occurredAt?: string;
    }): Promise<ConfirmInboundResult> => {
      const { data, error } = await supabase.rpc('e1_confirm_inbound', {
        p_order: input.orderId,
        p_actual_qty: input.actualQty,
        p_idempotency_key: input.idempotencyKey ?? makeInboundKey(input.orderId),
        p_occurred_at: input.occurredAt,
      });
      if (error) throw new Error(error.message);
      const r = (data ?? {}) as unknown as Record<string, unknown>;
      return {
        orderId: String(r.order_id ?? input.orderId),
        receivedQty: num(r.received_qty),
        unitPrice: numOrNull(r.unit_price),
        priceSpike: Boolean(r.price_spike),
        duplicate: Boolean(r.duplicate),
        alreadyReceived: Boolean(r.already_received),
      };
    },
    onSuccess: (_r, input) => invalidate(qc, invalidateOn.e1(input.ingredientId)),
  });
}

/** E12 발주 취소 — 아직 입고되지 않은 주문만. */
export function useCancelOrder() {
  const qc = useQueryClient();
  return useMutation({
    mutationFn: async (input: { orderId: string; reason?: string }) => {
      const { error } = await supabase.rpc('e12_order_canceled', {
        p_order: input.orderId,
        p_reason: input.reason,
      });
      if (error) throw new Error(error.message);
    },
    onSuccess: () => invalidate(qc, invalidateOn.e7()),
  });
}

/** E11 입고 취소 — 잘못 확정한 입고를 되돌린다. 재고·단가·추이가 함께 되돌아간다. */
export function useRevertInbound() {
  const qc = useQueryClient();
  return useMutation({
    mutationFn: async (input: { orderId: string; ingredientId: string; reason?: string }) => {
      const { error } = await supabase.rpc('e11_inbound_reverted', {
        p_order: input.orderId,
        p_reason: input.reason,
      });
      if (error) throw new Error(error.message);
    },
    onSuccess: (_r, input) => invalidate(qc, invalidateOn.e1(input.ingredientId)),
  });
}

/**
 * 레시피 조회·저장 훅.
 *
 * 손익(재료비·세금·고정지출·순이익률)은 **서버가 권위**다(절대원칙 3).
 * 앱은 받아서 그리기만 하고, 미리보기 계산이 필요하면 `@sikjae/core` 의 같은 공식을 쓴다.
 */
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { invalidate, invalidateOn, qk } from '@/lib/queryClient';
import { supabase } from '@/lib/supabase';
import { asJson } from '@/lib/json';
import {
  rpcNullableNumber as numOrNull,
  rpcNullableString as str,
  rpcNumber as num,
} from '@/lib/rpcValue';
import { useStoreId } from '@/lib/SessionProvider';
import { parseLastChange, type LastChange } from '@/features/changes/hooks';

const YM = /^\d{4}-(0[1-9]|1[0-2])$/;

/**
 * 고정지출 응답을 **검증**한다. 없으면 조회 오류로 올린다 — 조용히 넘기지 않는다.
 *
 * ⚠ 예전엔 `String(r.fixed_month ?? '')` · `(r.fixed_items ?? [])` 였다. 서버가 키를
 *   빠뜨리면 화면이 **거짓말을 하면서 멀쩡해 보인다** —
 *       항목 자리: `이번 달 고정지출이 아직 없어요`
 *       소계 자리: `3,756원 · 31.3%`   (fixedRate 는 따로 오므로 그대로 나온다)
 *   사장님은 고정지출을 지운 적이 없는데 지워졌다고 읽는다. 차라리 못 불러온 게 낫다.
 */
function reqFixed(r: Record<string, unknown>): { month: string; items: { key: string; total: number }[] } {
  const month = typeof r.fixed_month === 'string' ? r.fixed_month : '';
  if (!YM.test(month)) {
    throw new Error('서버가 고정지출 기준 월을 주지 않았어요. 잠시 후 다시 시도해 주세요');
  }
  if (!Array.isArray(r.fixed_items)) {
    throw new Error('서버가 고정지출 항목을 주지 않았어요. 잠시 후 다시 시도해 주세요');
  }
  return {
    month,
    // 항목 자체는 **비어 있어도 정상**이다 — 아직 안 적은 달이 그렇다.
    // 여기서 거르는 건 `배열이 아닌 것`, 즉 서버가 안 준 경우뿐이다.
    items: (r.fixed_items as Record<string, unknown>[]).map((i) => ({
      key: String(i.key ?? ''), total: num(i.total),
    })),
  };
}

export type TaxMode = 'included' | 'separate' | 'exempt';

/** 부가세 외 세금 항목 — 카드 수수료 등. rate 는 판매가 대비 %(0052). */
export interface TaxItem {
  name: string;
  rate: number;
}

/** '(−) 세금' 을 펼쳤을 때 보이는 한 줄. 부가세는 builtin. */
export interface TaxRow extends TaxItem {
  amount: number;
  builtin: boolean;
}

const taxItems = (v: unknown): TaxItem[] =>
  ((v ?? []) as Record<string, unknown>[]).map((i) => ({
    name: String(i.name ?? ''),
    rate: num(i.rate),
  }));

const taxRows = (v: unknown): TaxRow[] =>
  ((v ?? []) as Record<string, unknown>[]).map((i) => ({
    name: String(i.name ?? ''),
    rate: num(i.rate),
    amount: num(i.amount),
    builtin: i.builtin === true,
  }));

export interface RecipeRow {
  id: string;
  name: string;
  price: number;
  active: boolean;
  categoryId: string | null;
  categoryName: string | null;
  taxMode: TaxMode;
  baseServings: number;
  targetProfitRate: number;
  avgMonthlySales: number | null;
  materialCost: number;
  extraCost: number;
  tax: number;
  fixedCost: number;
  profit: number;
  /** 0~1 비율. 화면 표기는 formatPercent 가 맡는다. */
  profitRate: number;
  materialRate: number;
  /**
   * 기준단가가 없어 원가에서 **빠진** 재료 줄 수.
   * recipe_material_cost 는 단가 null 을 0 으로 넘기므로, 합계만 보면 공짜인지 빠진 건지 알 수 없다.
   */
  unknownCostLines: number;
  /**
   * 재고가 0 이라 이 메뉴를 못 만들게 하는 재료 이름. null 이면 만들 수 있다.
   * 서버가 판정한다(recipe_blocked_by) — 화면과 서버가 다른 기준을 쓰면 안 된다.
   */
  blockedBy: string | null;
}

export interface RecipeLine {
  id: string;
  ingredientId: string | null;
  subRecipeId: string | null;
  name: string;
  baseUnit: 'g' | 'ml' | 'ea' | null;
  /** 기준 인분 전체 사용량 */
  inputQty: number;
  /** 1인분 사용량 */
  perServing: number;
  /** 기준단가(원/기준단위). 산출 전이면 null — 0 으로 그리면 공짜 재료로 읽힌다. */
  unitPrice: number | null;
  /**
   * 현재 장부 재고(기준단위). **음수일 수 있다**(0102).
   * ⚠ 이 줄은 사용량·단가·원가와 다른 축이다. 원가는 음수가 되지 않는다 —
   *   음수인 것은 지금 창고에 얼마가 있느냐뿐이다.
   */
  stockTotal: number;
  safetyStock: number;
  soonOut: boolean;
}

export interface RecipeDetail {
  id: string;
  name: string;
  price: number;
  active: boolean;
  /** 최근 30일 판매 실적 — 레시피 화면에서 매출 탭으로 건너가지 않게. */
  sales30d: { qty: number; revenue: number; waste: number };
  /** 메뉴 메모. 식재료와 같은 자리에 같은 모양으로 보인다(0063). */
  memo: string | null;
  /** 상세 첫 카드 아래 한 줄에 쓸 마지막 변경(0063). */
  lastChange: LastChange;
  taxMode: TaxMode;
  /** 부가세 외 세금 항목(0052). 편집 화면이 그대로 고쳐 되보낸다. */
  taxItems: TaxItem[];
  /** 부가세를 포함한 항목별 내역 — 손익표의 '(−) 세금' 을 펼칠 때. */
  taxBreakdown: TaxRow[];
  tax: number;
  baseServings: number;
  targetProfitRate: number;
  avgMonthlySales: number | null;
  materialCost: number;
  extraCost: number;
  fixedRate: number;
  /**
   * ⚠ `fixedRate` 를 낸 **그 달**과 **그 달의 항목**이다(0128). 서버가 한 문장에서
   *   같이 낸다 — 앱이 따로 고정지출을 조회하면 매장 자정 사이에 두 요청이 갈려
   *   9월 비율을 8월 항목으로 쪼갤 수 있다(합계는 맞고 줄마다 틀린다).
   */
  fixedMonth: string;
  fixedItems: { key: string; total: number }[];
  categoryId: string | null;
  lines: RecipeLine[];
  extras: { id: string; name: string; amount: number; materialId: string | null; qty: number }[];
}

export function useRecipeList() {
  const storeId = useStoreId();
  return useQuery({
    queryKey: qk.recipes,
    queryFn: async (): Promise<RecipeRow[]> => {
      const { data, error } = await supabase.rpc('recipe_list', { p_store: storeId });
      if (error) throw new Error(error.message);
      return ((data ?? []) as Record<string, unknown>[]).map((r) => ({
        id: String(r.id),
        name: String(r.name),
        price: num(r.price),
        active: r.active !== false,
        categoryId: str(r.category_id),
        categoryName: str(r.category_name),
        taxMode: r.tax_mode as TaxMode,
        baseServings: num(r.base_servings),
        targetProfitRate: num(r.target_profit_rate),
        avgMonthlySales: numOrNull(r.avg_monthly_sales),
        materialCost: num(r.material_cost),
        extraCost: num(r.extra_cost),
        tax: num(r.tax),
        fixedCost: num(r.fixed_cost),
        profit: num(r.profit),
        profitRate: num(r.profit_rate),
        materialRate: num(r.material_rate),
        unknownCostLines: num(r.unknown_cost_lines),
        blockedBy: str(r.blocked_by),
      }));
    },
  });
}

export function useRecipeDetail(id: string | undefined) {
  return useQuery({
    queryKey: qk.recipe(id ?? ''),
    enabled: Boolean(id),
    queryFn: async (): Promise<RecipeDetail | null> => {
      const { data, error } = await supabase.rpc('recipe_detail', { p_recipe: id as string });
      if (error) throw new Error(error.message);
      if (!data) return null;
      const r = data as unknown as Record<string, unknown>;
      // 던지면 react-query 가 오류로 잡고, 화면의 QueryState 가 재시도를 준다.
      const fixed = reqFixed(r);
      return {
        id: String(r.id),
        name: String(r.name),
        price: num(r.price),
        active: r.active !== false,
        sales30d: {
          qty: num((r.sales_30d as Record<string, unknown> | null)?.qty),
          revenue: num((r.sales_30d as Record<string, unknown> | null)?.revenue),
          waste: num((r.sales_30d as Record<string, unknown> | null)?.waste),
        },
        memo: str(r.memo),
        lastChange: parseLastChange(r.last_change),
        taxMode: r.tax_mode as TaxMode,
        taxItems: taxItems(r.tax_items),
        taxBreakdown: taxRows(r.tax_breakdown),
        tax: num(r.tax),
        baseServings: num(r.base_servings),
        targetProfitRate: num(r.target_profit_rate),
        avgMonthlySales: numOrNull(r.avg_monthly_sales),
        materialCost: num(r.material_cost),
        extraCost: num(r.extra_cost),
        fixedRate: num(r.fixed_rate),
        fixedMonth: fixed.month,
        fixedItems: fixed.items,
        categoryId: str(r.category_id),
        lines: ((r.lines ?? []) as Record<string, unknown>[]).map((l) => ({
          id: String(l.id),
          ingredientId: str(l.ingredient_id),
          subRecipeId: str(l.sub_recipe_id),
          name: String(l.name ?? ''),
          baseUnit: (l.base_unit as RecipeLine['baseUnit']) ?? null,
          inputQty: num(l.input_qty),
          perServing: num(l.per_serving),
          unitPrice: numOrNull(l.unit_price),
          stockTotal: num(l.stock_total),
          safetyStock: num(l.safety_stock),
          soonOut: Boolean(l.soon_out),
        })),
        extras: ((r.extras ?? []) as Record<string, unknown>[]).map((e) => ({
          id: String(e.id),
          name: String(e.name),
          amount: num(e.amount),
          materialId: str(e.material_id),
          qty: num(e.qty) || 1,
        })),
      };
    },
  });
}

export interface RecipeInput {
  id?: string;
  name: string;
  price: number;
  categoryId?: string | null;
  active?: boolean;
  memo?: string | null;
  /*
   * ⚠ 세금은 여기 없다(0087). 매장 설정(MY > 세금)이 정하고 서버 트리거가
   *   레시피에 실어 준다 — 레시피 저장으로는 세금을 못 바꾼다.
   *   값이 바뀌는 길은 하나여야 한다(절대원칙 2 와 같은 이유).
   */
  baseServings: number;
  targetProfitRate: number;
  avgMonthlySales: number | null;
  /** 보내면 **전량 교체**된다. 헤더만 고칠 때는 생략한다. */
  lines?: { ingredientId?: string | null; subRecipeId?: string | null; inputQty: number }[];
  /** 부자재 마스터를 가리키면 금액은 서버가 마스터 단가 × 수량으로 계산한다. */
  extras?: { materialId?: string | null; name?: string; amount?: number; qty?: number }[];
}

export function useSaveRecipe() {
  const qc = useQueryClient();
  const storeId = useStoreId();
  return useMutation({
    mutationFn: async (input: RecipeInput): Promise<string> => {
      const payload: Record<string, unknown> = {
        id: input.id ?? '',
        name: input.name,
        price: input.price,
        base_servings: input.baseServings,
        target_profit_rate: input.targetProfitRate,
        avg_monthly_sales: input.avgMonthlySales ?? '',
      };
      if (input.memo !== undefined) payload.memo = input.memo ?? '';
      if (input.categoryId !== undefined) payload.category_id = input.categoryId ?? '';
      if (input.active !== undefined) payload.active = input.active;
      if (input.lines) {
        payload.lines = input.lines.map((l) => ({
          ingredient_id: l.ingredientId ?? '',
          /*
           * ⚠ `sub_recipe_id` 를 보내지 않는다(0109). 반제품은 1차 범위 밖이고,
           *   서버도 값이 들어오면 거부한다. 예전엔 `''` 를 보내고 있었는데,
           *   빈 문자열이라 통과했을 뿐 **보내는 자리가 남아 있다는 게 문제**였다 —
           *   화면 하나만 채우면 예약 컬럼이 곧바로 기능이 된다.
           */
          input_qty: l.inputQty,
        }));
      }
      if (input.extras) {
        payload.extras = input.extras.map((e) => ({
          material_id: e.materialId ?? '',
          name: e.name ?? '',
          amount: e.amount ?? 0,
          qty: e.qty ?? 1,
        }));
      }
      const { data, error } = await supabase.rpc('save_recipe', { p_store: storeId, p_payload: asJson(payload) });
      if (error) throw new Error(error.message);
      return String(data);
    },
    onSuccess: (id) => invalidate(qc, invalidateOn.e3(id)),
  });
}

export function useDeactivateRecipe() {
  const qc = useQueryClient();
  return useMutation({
    mutationFn: async (id: string) => {
      const { error } = await supabase.rpc('deactivate_recipe', { p_recipe: id });
      if (error) throw new Error(error.message);
    },
    onSuccess: (_r, id) => invalidate(qc, invalidateOn.e3(id)),
  });
}

/** 반제품 후보 — 레시피 재료로 넣을 수 있는 다른 메뉴(자기 자신 제외). */
export function useRecipePickList(excludeId?: string) {
  const storeId = useStoreId();
  return useQuery({
    queryKey: [...qk.recipes, 'pick', excludeId ?? ''],
    queryFn: async (): Promise<{ id: string; name: string; baseServings: number; unitCost: number; active: boolean }[]> => {
      const { data, error } = await supabase.rpc('recipe_pick_list', {
        p_store: storeId,
        p_exclude: excludeId,
      });
      if (error) throw new Error(error.message);
      return ((data ?? []) as Record<string, unknown>[]).map((r) => ({
        id: String(r.id),
        name: String(r.name),
        baseServings: num(r.base_servings),
        unitCost: num(r.unit_cost),
        active: r.active !== false,
      }));
    },
  });
}

/**
 * RCP-16 손익 변동 — `recipe_profit_history()` 한 개만 쓴다.
 *
 * 수정 내역(0063)과 질문이 다르다.
 *   수정 내역 — 누가 무엇을 고쳤나 · 오늘 매출에 반영됐나   (화면 7일 · 서버 30일)
 *   손익 변동 — 그래서 순이익이 얼마에서 얼마로 움직였나   (영구)
 * 그래서 여기에는 직접 수정/자동 갱신도, 매출 반영 배지도 없다.
 *
 * ⚠ 금액은 **서버 스냅샷 그대로** 쓴다. 화면에서 다시 빼고 더하지 않는다 —
 *   판매가를 500원 올려도 순이익은 500원 오르지 않는다(세금·고정지출이 따라 움직인다).
 */
import { useInfiniteQuery } from '@tanstack/react-query';
import type { ProfitCauseKey } from '@sikjae/core';
import { supabase } from '@/lib/supabase';
import { qk } from '@/lib/queryClient';
import { rpcNullableString } from '@/lib/rpcValue';

export interface ProfitCauseRow {
  key: ProfitCauseKey;
  label: string;
  before: number;
  after: number;
}

export interface ProfitChange {
  id: string;
  occurredAt: string;
  /** `고춧가루 단가 반영` · `고정지출 반영` · `레시피 수정` */
  title: string;
  /** `재료비 32원 감소` — 대표 원인 한 줄. */
  summary: string | null;
  /** 시트 부제 — 재료 이름 · `고정지출 설정` · `직접 수정`. */
  sourceLabel: string | null;
  cause: ProfitCauseRow | null;
  profitBefore: number | null;
  profitAfter: number;
  /** 직전 대비 증감. 비교 대상이 없으면 null. */
  profitDelta: number | null;
  rateBefore: number | null;
  rateAfter: number;
}

export interface ProfitCursor {
  occurredAt: string;
  id: string;
}

const num = (v: unknown): number | null =>
  v === null || v === undefined || v === '' ? null : Number(v);

/**
 * ⚠ 빠진 금액을 0원으로 메꾸지 않는다. 사장님은 순이익이 진짜 그만큼 떨어진 줄 안다.
 *   서버도 반쪽 스냅샷이면 거절한다(0083) — 여기는 그 계약의 앱 쪽 절반이다.
 */
function parseChange(raw: unknown): ProfitChange {
  const r = (raw ?? {}) as Record<string, unknown>;
  const after = num(r.profit_after);
  const rate = num(r.rate_after);
  if (after === null || rate === null) {
    throw new Error('손익 스냅샷에 순이익이 없습니다. 서버 recipe_profit_history() 와 어긋났습니다.');
  }

  const causeKey = rpcNullableString(r.cause_key);
  const before = num(r.cause_before);
  const causeAfter = num(r.cause_after);

  return {
    id: String(r.id),
    occurredAt: String(r.occurred_at),
    title: String(r.title ?? ''),
    summary: rpcNullableString(r.summary),
    sourceLabel: rpcNullableString(r.source_label),
    cause:
      causeKey !== null && before !== null && causeAfter !== null
        ? {
            key: causeKey as ProfitCauseKey,
            label: String(r.cause_label ?? ''),
            before,
            after: causeAfter,
          }
        : null,
    profitBefore: num(r.profit_before),
    profitAfter: after,
    profitDelta: num(r.profit_delta),
    rateBefore: num(r.rate_before),
    rateAfter: rate,
  };
}

/** 20건씩. 커서는 (시각, id) 다 — 같은 날 세 번 고친 순서를 날짜만으로는 못 지킨다. */
export function useProfitHistory(recipeId: string | undefined, pageSize = 20) {
  return useInfiniteQuery({
    queryKey: [...qk.recipe(recipeId ?? ''), 'profit-history', pageSize],
    enabled: Boolean(recipeId),
    initialPageParam: null as ProfitCursor | null,
    queryFn: async ({ pageParam }) => {
      const { data, error } = await supabase.rpc('recipe_profit_history', {
        p_recipe: recipeId as string,
        p_before: pageParam?.occurredAt ?? undefined,
        p_before_id: pageParam?.id ?? undefined,
        p_limit: pageSize,
      });
      if (error) throw new Error(error.message);
      const r = (data ?? {}) as unknown as Record<string, unknown>;
      const next = (r.next ?? null) as Record<string, unknown> | null;
      return {
        items: ((r.rows ?? []) as unknown[]).map(parseChange),
        next: next
          ? ({ occurredAt: String(next.occurred_at), id: String(next.id) } satisfies ProfitCursor)
          : null,
      };
    },
    getNextPageParam: (last) => last.next,
  });
}

/** 증감 한 줄의 색과 문구. 0원은 `변동 없음` 이다 — `+0원`은 아무 말도 아니다. */
export function deltaTone(delta: number | null): 'up' | 'down' | 'flat' {
  if (delta === null || Math.abs(delta) < 0.005) return 'flat';
  return delta > 0 ? 'up' : 'down';
}

/**
 * 매출 조회·저장 훅.
 *
 * 여기가 사이클의 마지막 고리다. 메뉴를 팔면 서버가 그날 스냅샷의 직접 식재료 라인을 사용해
 * **식재료 재고까지 차감**한다(E10 → E8). 반제품은 1차 입력이 금지돼 있다. 그래서 저장 후에는 매출뿐 아니라
 * 재고·발주 후보 캐시도 함께 버려야 한다 — 안 그러면 "팔았는데 식재료 화면은 그대로"가 된다.
 */
import { useCallback } from 'react';
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { invalidate, invalidateOn, qk } from '@/lib/queryClient';
import {
  rpcNullableNumber as numOrNull,
  rpcNullableString as str,
  rpcNumber as num,
} from '@/lib/rpcValue';
import { supabase, rpcError } from '@/lib/supabase';
import { useStoreId } from '@/lib/SessionProvider';
// 응답 계약 검사는 **앱 의존 없는 한 모듈**에 둔다 — 시험이 본체를 그대로 돌릴 수 있게.
import {
  CONTRACT_HINT, parseAmendResultContract, parseSalesDayContract,
  type SalesDayBasisQuality, type SalesDayStatus,
} from './dayContract';

/** 손익 한 장. 서버 `sales_summary()` 가 유일한 계산 주체다(절대원칙 3). */
export interface SalesSummary {
  from: string;
  to: string;
  days: number;
  revenue: number;
  etcRevenue: number;
  qty: number;
  materialCost: number;
  extraMaterialCost: number;
  tax: number;
  wasteLoss: number;
  wasteIngredient: number;
  wasteMenu: number;
  dailyExtra: number;
  fixedCost: number;
  fixedRate: number | null;
  /** 해당 월 고정지출이 없어 과거 월 값을 빌려 쓴 상태. 화면이 "잠정"이라 표시해야 한다. */
  fixedRateProvisional: boolean;
  profit: number;
}

export interface SaleItem {
  id: string;
  recipeId: string | null;
  menuName: string;
  unitPrice: number;
  unitMaterialCost: number;
  unitExtraCost: number;
  qtyHall: number;
  qtyDelivery: number;
  qtyTakeout: number;
  /** 조리 폐기 — 재료는 나갔고 매출은 0. */
  qtyWaste: number;
  qty: number;
}

/** 채널은 매장·배달앱·포장 **3개 고정**이다(0043). 네 번째는 없다. */
export type ChannelCode = 'hall' | 'delivery' | 'takeout';
export const CHANNEL_CODES: ChannelCode[] = ['hall', 'delivery', 'takeout'];

export interface EtcItem {
  name: string;
  price: number;
  qty: number;
  /**
   * 판매 채널(0093). **없을 수 있다** — 채널을 묻기 전에 적은 옛 줄이다.
   * ⚠ 없다고 매장으로 치면 안 된다. 모르는 것이지 매장인 게 아니다.
   */
  channel?: ChannelCode;
}
export interface ExtraItem { name: string; amount: number; memo?: string }

/**
 * 그날 손익을 무엇을 기준으로 계산했나(0144·0149). 장부가 없으면 null.
 * 정의는 `dayContract` 한 곳에 있다 — 응답을 검사하는 곳과 화면이 쓰는 곳이 갈리면
 * 한쪽만 고쳐지는 날이 온다.
 */
export type BasisQuality = SalesDayBasisQuality;

export interface SalesDay {
  saleDate: string;
  /**
   * 그날 매출의 판본(0117). 저장할 때 **그대로 되보낸다**.
   * 서버 값과 다르면 이 화면은 낡은 것이고, 저장은 45009 로 거부된다 —
   * 그게 다른 기기가 적은 판매를 조용히 지우지 않게 하는 유일한 장치다.
   */
  revision: number;
  items: SaleItem[];
  etcItems: EtcItem[];
  extraItems: ExtraItem[];
  etcRevenue: number;
  dailyExtra: number;
  summary: SalesSummary;
  /**
   * 그날 원가·손익의 계산 기준(0153). `estimated_current` 면 화면이
   * `원가·손익은 현재 기준으로 계산했어요` 를 보여 준다.
   * ⚠ 매출과 판매 수량은 사장님이 적은 **실제 기록**이다. `전체가 추정` 처럼 말하면 안 된다.
   * ⚠ 장부가 없으면 null 이다 — 없는 것과 정확한 것은 다르다. `exact` 로 채우지 않는다.
   */
  basisQuality: BasisQuality | null;
  /** 그날 영업일 장부가 있나. 없으면 §6.4 의 `판매 내역 추가` 자리다. */
  hasLedger: boolean;
  /**
   * 장부 상태. `closed` 면 정정 RPC 로, 그 밖이면 오늘 판매 화면으로 간다.
   * ⚠ `none` 은 없다 — 장부가 없으면 null 이다(`dayContract` 참고).
   */
  dayStatus: SalesDayStatus | null;
  /** 고칠 수 있는 기간인가(지난달 1일~오늘). **서버가 정한다** — 앱이 두 벌 갖지 않는다. */
  editable: boolean;
}

export function parseSummary(v: unknown): SalesSummary {
  const r = (v ?? {}) as Record<string, unknown>;
  return {
    from: String(r.from ?? ''),
    to: String(r.to ?? ''),
    days: num(r.days),
    revenue: num(r.revenue),
    etcRevenue: num(r.etc_revenue),
    qty: num(r.qty),
    materialCost: num(r.material_cost),
    extraMaterialCost: num(r.extra_material_cost),
    tax: num(r.tax),
    wasteLoss: num(r.waste_loss),
    wasteIngredient: num(r.waste_ingredient),
    wasteMenu: num(r.waste_menu),
    dailyExtra: num(r.daily_extra),
    fixedCost: num(r.fixed_cost),
    fixedRate: numOrNull(r.fixed_rate),
    fixedRateProvisional: Boolean(r.fixed_rate_provisional),
    profit: num(r.profit),
  };
}

/** 하루 장부 (SALES-01 / SALES-03). 판매 기록이 없는 날도 빈 장부를 돌려준다. */
export function useSalesDay(date: string) {
  const storeId = useStoreId();
  return useQuery({
    queryKey: qk.salesDay(date),
    /*
     * ⚠ 날짜가 빈 문자열이면 **조회하지 않는다**(0125). 서버가 장부 날짜를 알려 주기
     *   전에는 어느 날을 물어야 할지 모른다. 앱이 직접 계산해서 메우면 그게 곧
     *   앱과 DB 가 각자 오늘을 계산하는 상태다(기획서 §2.1).
     *   빈 화면이 잘못된 날의 장부보다 낫다.
     */
    enabled: Boolean(storeId) && Boolean(date),
    queryFn: async (): Promise<SalesDay> => {
      const { data, error } = await supabase.rpc('sales_day', { p_store: storeId, p_date: date });
      if (error) throw new Error(error.message);
      const r = (data ?? null) as unknown as Record<string, unknown> | null;
      /*
       * ⚠ 0153 부터 서버는 **기록 없는 날도 한 줄로** 답한다. 답이 없다는 건 빈 장부가
       *   아니라 계약이 어긋났다는 뜻이다 — 빈 장부로 메우면 화면은 멀쩡해 보이는데
       *   `수정할 수 없는 날` 처럼 보인다.
       */
      if (!r) throw new Error(`${CONTRACT_HINT} (sales_day)`);
      return {
        saleDate: String(r.sale_date ?? date),
        // ⚠ `revision` 은 아래 `parseSalesDayContract` 가 준다. 여기서 `num(...)` 으로 읽으면
        //   서버가 빠뜨렸을 때 0 이 되고, 그 0 을 들고 저장하러 갔다가 45009 를 맞는다.
        etcRevenue: num(r.etc_revenue),
        dailyExtra: num(r.daily_extra),
        etcItems: ((r.etc_items ?? []) as Record<string, unknown>[]).map((e) => ({
          name: String(e.name ?? ''), price: num(e.price), qty: num(e.qty),
          channel: CHANNEL_CODES.includes(e.channel as ChannelCode) ? (e.channel as ChannelCode) : undefined,
        })),
        extraItems: ((r.extra_items ?? []) as Record<string, unknown>[]).map((e) => ({
          name: String(e.name ?? ''), amount: num(e.amount), memo: str(e.memo) ?? undefined,
        })),
        items: ((r.items ?? []) as Record<string, unknown>[]).map((it) => ({
          id: String(it.id),
          recipeId: str(it.recipe_id),
          menuName: String(it.menu_name),
          unitPrice: num(it.unit_price),
          unitMaterialCost: num(it.unit_material_cost),
          unitExtraCost: num(it.unit_extra_cost),
          qtyHall: num(it.qty_hall),
          qtyDelivery: num(it.qty_delivery),
          qtyTakeout: num(it.qty_takeout),
          qtyWaste: num(it.qty_waste),
          qty: num(it.qty),
        })),
        summary: parseSummary(r.summary),
        /*
         * ⚠ 넷을 **한 번에** 읽는다. 하나씩 보면 서로 모순된 응답이 통과한다 —
         *   `has_ledger: true` 인데 `basis_quality`·`day_status` 가 둘 다 null 이면
         *   화면은 배지를 안 그리고 정정 버튼만 띄운다(0153 검토).
         */
        ...parseSalesDayContract(r),
      };
    },
  });
}

export interface RangeDay { date: string; revenue: number; qty: number; material: number; profit: number }
export interface RangeMenu {
  recipeId: string | null;
  menuName: string;
  qty: number;
  qtyHall: number;
  qtyDelivery: number;
  qtyTakeout: number;
  qtyWaste: number;
  revenue: number;
  unitPrice: number;
  unitMaterialCost: number;
  material: number;
}
export interface RangeChannel {
  code: string;
  name: string;
  amount: number;
  qty: number;
  /** 채널별 수량이 있으므로 배분이 아니라 정확히 나뉜 값. */
  material: number;
  tax: number;
}

export interface SalesRange {
  from: string;
  to: string;
  summary: SalesSummary;
  daily: RangeDay[];
  menu: RangeMenu[];
  channels: RangeChannel[];
}

/** 기간 분석 (SALES-02). 날짜마다 조회하면 30일에 30 왕복이 되므로 한 번에 받는다. */
export function useSalesRange(from: string, to: string, enabled = true) {
  const storeId = useStoreId();
  return useQuery({
    queryKey: qk.salesRange(from, to),
    enabled: enabled && Boolean(from) && Boolean(to),
    queryFn: async (): Promise<SalesRange> => {
      const { data, error } = await supabase.rpc('sales_range', { p_store: storeId, p_from: from, p_to: to });
      if (error) throw new Error(error.message);
      const r = (data ?? {}) as unknown as Record<string, unknown>;
      return {
        from, to,
        summary: parseSummary(r.summary),
        daily: ((r.daily ?? []) as Record<string, unknown>[]).map((d) => ({
          date: String(d.date), revenue: num(d.revenue), qty: num(d.qty),
          material: num(d.material), profit: num(d.profit),
        })),
        menu: ((r.menu ?? []) as Record<string, unknown>[]).map((m) => ({
          recipeId: str(m.recipe_id),
          menuName: String(m.menu_name),
          qty: num(m.qty),
          qtyHall: num(m.qty_hall),
          qtyDelivery: num(m.qty_delivery),
          qtyTakeout: num(m.qty_takeout),
          qtyWaste: num(m.qty_waste),
          revenue: num(m.revenue),
          unitPrice: num(m.unit_price),
          unitMaterialCost: num(m.unit_material_cost),
          material: num(m.material),
        })),
        channels: ((r.channels ?? []) as Record<string, unknown>[]).map((c) => ({
          code: String(c.code), name: String(c.name),
          amount: num(c.amount), qty: num(c.qty), material: num(c.material),
          tax: num(c.tax),
        })),
      };
    },
  });
}

/** 판매 한 줄. 저장과 부족 판정이 **같은 모양**을 쓴다 — 갈리면 미리보기가 거짓말이 된다. */
export interface SaleItemInput {
  recipeId: string;
  qtyHall: number;
  qtyDelivery: number;
  qtyTakeout: number;
  qtyWaste?: number;
}

/** 부족 판정의 종류. 화면이 `안전재고` 를 쓸지 `필요 수량` 을 쓸지 가른다(기획안 §4.4). */
export type ShortageMode = 'start' | 'sale';

export interface SaveSaleInput {
  date: string;
  items: SaleItemInput[];
  /**
   * 화면이 마지막으로 본 판본(0117).
   *
   * ⚠ **필수다.** 예전엔 선택값(`?:`)이었는데, 그러면 나중에 저장 경로가 하나
   *   늘어날 때 빼먹어도 타입체크가 통과한다 — 그 경로로 낡은 화면이 남의 기록을
   *   조용히 덮어쓴다. 빼먹을 수 없게 만드는 게 유일하게 믿을 만한 방어다.
   *
   *   조회가 끝나기 전에는 저장 자체를 막는다(버튼 비활성).
   *   생략을 허용하는 건 DB 함수 쪽뿐이다 — 시드와 서버 내부 호출용이다.
   */
  baseRevision: number;
  /**
   * 영업 전(45001)에서 확인을 받은 뒤의 재시도만 true 로 보낸다(0154).
   * 서버가 영업 시작 + 저장을 **한 트랜잭션**으로 한다 — 예전엔 RPC 두 번이라
   * 열기만 되고 저장이 죽으면 빈 영업일이 남았다.
   */
  openDay?: boolean;
  /** 늦은 개점(45015) 뒤 고른 오늘 마칠 시간 'HH:MM' — openDay 재시도에만 싣는다(0162). */
  openCloseTime?: string;
  /** 생략하면 그날 값을 그대로 둔다. 빈 배열을 보내면 전부 지운다. */
  etcItems?: EtcItem[];
  extraItems?: ExtraItem[];
}

/** 재고가 모자란 채로 팔린 항목 — 화면이 "재고 기록이 실제와 다를 수 있어요"를 알려야 한다. */
export interface Shortage { ingredientId: string; name: string; needed: number; available: number; shortage: number }

/**
 * 그날 기준 메뉴 손익 세부 — 판매가·재료 줄·부자재 항목·고정지출 항목까지
 * **영업 시작 시점 값**이다(0051).
 *
 * ⚠ 레시피 상세(useRecipeDetail)를 쓰면 안 된다. 그건 "지금 팔면 얼마 남나"라
 *   레시피를 고치는 순간 지난 날짜의 세부까지 따라 움직인다. 여기는 장부다.
 */
export interface DayMenuLine {
  ingredientId: string; name: string; baseUnit: 'g' | 'ml' | 'ea';
  perServing: number; unitPrice: number | null; amount: number;
}
export interface DayMenuExtra { name: string; qty: number; amount: number }
export interface DayMenuFixedItem { key: string; amount: number; rate: number }
export interface DayMenuDetail {
  sold: boolean;
  name: string;
  qty: number; qtyWaste: number; qtyHall: number; qtyDelivery: number; qtyTakeout: number;
  baseServings: number;
  taxMode: 'included' | 'separate' | 'exempt';
  price: number; materialCost: number; extraCost: number;
  fixedRate: number; fixedCost: number; tax: number; profit: number;
  /** 그날 세금 항목별 내역(부가세 포함). 나중에 요율을 고쳐도 이건 안 움직인다(0054). */
  taxItems: { name: string; rate: number; amount: number; builtin: boolean }[];
  lines: DayMenuLine[]; extras: DayMenuExtra[]; fixedItems: DayMenuFixedItem[];
}

export function useDayMenuDetail(date: string | undefined, recipeId: string | undefined) {
  const storeId = useStoreId();
  return useQuery({
    queryKey: [...qk.salesDay(date ?? ''), 'menu', recipeId ?? ''],
    enabled: Boolean(storeId && date && recipeId),
    queryFn: async (): Promise<DayMenuDetail> => {
      const { data, error } = await supabase.rpc('day_menu_detail', {
        p_store: storeId, p_date: date as string, p_recipe: recipeId as string,
      });
      if (error) throw new Error(error.message);
      const r = (data ?? {}) as unknown as Record<string, unknown>;
      const arr = (k: string) => (r[k] ?? []) as Record<string, unknown>[];
      return {
        sold: Boolean(r.sold),
        name: String(r.name ?? ''),
        qty: num(r.qty), qtyWaste: num(r.qty_waste),
        qtyHall: num(r.qty_hall), qtyDelivery: num(r.qty_delivery), qtyTakeout: num(r.qty_takeout),
        baseServings: num(r.base_servings),
        taxMode: (r.tax_mode ?? 'included') as DayMenuDetail['taxMode'],
        price: num(r.price), materialCost: num(r.material_cost), extraCost: num(r.extra_cost),
        fixedRate: num(r.fixed_rate), fixedCost: num(r.fixed_cost),
        tax: num(r.tax), profit: num(r.profit),
        taxItems: arr('tax_items').map((t) => ({
          name: String(t.name ?? ''), rate: num(t.rate), amount: num(t.amount),
          builtin: t.builtin === true,
        })),
        lines: arr('lines').map((l) => ({
          ingredientId: String(l.ingredient_id), name: String(l.name),
          baseUnit: (l.base_unit ?? 'g') as DayMenuLine['baseUnit'],
          perServing: num(l.per_serving), unitPrice: numOrNull(l.unit_price), amount: num(l.amount),
        })),
        extras: arr('extras').map((e) => ({ name: String(e.name), qty: num(e.qty), amount: num(e.amount) })),
        fixedItems: arr('fixed_items').map((i) => ({ key: String(i.key), amount: num(i.amount), rate: num(i.rate) })),
      };
    },
  });
}

/**
 * 기간 메뉴 손익 — 날마다 그날 기준으로 계산해 **합산**한 값이다(0059).
 *
 * 사장님: "a재료 값을 10번 수정했어. 합계해서 보여준다고 해둬 — 어떤 합도 보여줘야 하잖아."
 * 그래서 평균이 아니라 합이다. 개당 값은 합 나누기 수량이라 '기간 평균'이라 부른다.
 */
export interface RangeMenuDetail {
  sold: boolean;
  name: string;
  days: number;
  qty: number; qtyWaste: number; qtyHall: number; qtyDelivery: number; qtyTakeout: number;
  /** 기간 합계 */
  revenue: number; materialCost: number; wasteMenu: number;
  extraCost: number; fixedCost: number; tax: number; profit: number;
  /** 개당(= 합 나누기 수량). 기간 중 값이 바뀌었으면 한 숫자로 말할 수 없다. */
  unitPrice: number; unitMaterialCost: number; unitExtraCost: number;
  unitFixedCost: number; unitTax: number; unitProfit: number;
  /** 기간에 판매가가 몇 가지였나. 하나뿐이면 길이 1. */
  pricePoints: { price: number; qty: number; days: number; from: string; to: string }[];
  lines: DayMenuLine[];
  extras: DayMenuExtra[];
  fixedItems: DayMenuFixedItem[];
}

export function useRangeMenuDetail(from: string | undefined, to: string | undefined, recipeId: string | undefined) {
  const storeId = useStoreId();
  return useQuery({
    queryKey: [...qk.salesRange(from ?? '', to ?? ''), 'menu', recipeId ?? ''],
    enabled: Boolean(storeId && from && to && recipeId),
    queryFn: async (): Promise<RangeMenuDetail> => {
      const { data, error } = await supabase.rpc('range_menu_detail', {
        p_store: storeId, p_from: from as string, p_to: to as string, p_recipe: recipeId as string,
      });
      if (error) throw new Error(error.message);
      const r = (data ?? {}) as unknown as Record<string, unknown>;
      const arr = (k: string) => (r[k] ?? []) as Record<string, unknown>[];
      const qty = num(r.qty);
      return {
        sold: Boolean(r.sold),
        name: String(r.name ?? ''),
        days: num(r.days),
        qty, qtyWaste: num(r.qty_waste),
        qtyHall: num(r.qty_hall), qtyDelivery: num(r.qty_delivery), qtyTakeout: num(r.qty_takeout),
        revenue: num(r.revenue), materialCost: num(r.material_cost), wasteMenu: num(r.waste_menu),
        extraCost: num(r.extra_cost), fixedCost: num(r.fixed_cost),
        tax: num(r.tax), profit: num(r.profit),
        unitPrice: num(r.unit_price), unitMaterialCost: num(r.unit_material_cost),
        unitExtraCost: num(r.unit_extra_cost), unitFixedCost: num(r.unit_fixed_cost),
        unitTax: num(r.unit_tax), unitProfit: num(r.unit_profit),
        pricePoints: arr('price_points').map((x) => ({
          price: num(x.price), qty: num(x.qty), days: num(x.days),
          from: String(x.from), to: String(x.to),
        })),
        lines: arr('lines').map((l) => ({
          ingredientId: String(l.ingredient_id), name: String(l.name),
          baseUnit: (l.base_unit ?? 'g') as DayMenuLine['baseUnit'],
          perServing: num(l.per_serving), unitPrice: numOrNull(l.unit_price), amount: num(l.amount),
        })),
        // 부자재 금액은 기간 합이다. 화면은 1인분 기준으로 그리므로 개당으로 환산한다.
        extras: arr('extras').map((e) => ({
          name: String(e.name), qty: num(e.qty),
          amount: qty > 0 ? num(e.amount) / qty : 0,
        })),
        fixedItems: arr('fixed_items').map((i) => ({
          key: String(i.key),
          amount: qty > 0 ? num(i.amount) / qty : 0,
          rate: num(r.unit_price) > 0 && qty > 0 ? num(i.amount) / qty / num(r.unit_price) : 0,
        })),
      };
    },
  });
}

export interface SaveSaleResult {
  /** 부족분 — 오류가 아니라 이미 팔린 것이다. */
  shortages: Shortage[];
  /** 이 저장이 영업 시작을 겸했나(0154). 화면이 안내와 상태 카드 갱신에 쓴다. */
  dayOpened: boolean;
}

export function useSaveSale() {
  const qc = useQueryClient();
  const storeId = useStoreId();
  return useMutation({
    mutationFn: async (input: SaveSaleInput): Promise<SaveSaleResult> => {
      const { data, error } = await supabase.rpc('save_sale', {
        p_store: storeId,
        p_date: input.date,
        p_items: input.items.map((i) => ({
          recipe_id: i.recipeId,
          qty_hall: i.qtyHall,
          qty_delivery: i.qtyDelivery,
          qty_takeout: i.qtyTakeout,
          qty_waste: i.qtyWaste ?? 0,
        })),
        p_etc_items: input.etcItems
          ? input.etcItems.map((e) => ({ name: e.name, price: e.price, qty: e.qty, channel: e.channel ?? null }))
          : undefined,
        p_extra_items: input.extraItems
          ? input.extraItems.map((e) => ({ name: e.name, amount: e.amount, memo: e.memo ?? '' }))
          : undefined,
        p_base_revision: input.baseRevision,
        p_open_day: input.openDay ?? false,
        p_open_close_time: input.openCloseTime ?? undefined,
      });
      // ⚠ 코드를 살려 던진다(0145). 화면이 문구가 아니라 SQLSTATE 로 가른다.
      if (error) throw rpcError(error);

      // 부족분은 오류가 아니다 — 이미 팔린 것이다. 화면에 알려주기 위해 모아 돌려준다.
      const results = ((data as unknown as Record<string, unknown>)?.items ?? []) as Record<string, unknown>[];
      const out: Shortage[] = [];
      for (const res of results) {
        const consume = (res?.consume ?? {}) as Record<string, unknown>;
        for (const s of (consume.shortages ?? []) as Record<string, unknown>[]) {
          out.push({
            ingredientId: String(s.ingredient_id),
            name: String(s.name),
            needed: num(s.needed),
            available: num(s.available),
            shortage: num(s.shortage),
          });
        }
      }
      return { shortages: out, dayOpened: (data as unknown as Record<string, unknown>)?.day_opened === true };
    },
    // 영업 시작을 겸했으면 상태 카드도 다시 그려야 한다 — 안 하면 카드가 '영업 전' 인 채
    // 판매만 쌓인다.
    onSuccess: (r, input) => invalidate(qc, [
      ...invalidateOn.e10(), qk.salesDay(input.date),
      ...(r.dayOpened ? invalidateOn.businessDay() : []),
    ]),
  });
}


// ── 과거 정정 (§6.4) ──────────────────────────────────────────

export interface AmendPastSaleInput {
  date: string;
  /**
   * 화면이 마지막으로 본 판본. `useSaveSale` 과 같은 이유로 **필수다**(0146).
   * ⚠ 이 값은 `sales_day.revision` 이다. 응답의 `auditRevisionNo`(정정 횟수)와 다른 값이니
   *   섞으면 다음 저장이 곧바로 45009 로 튕긴다 — 실제로 그랬다(0147).
   */
  baseRevision: number;
  /** 안 보낸 메뉴는 그대로 둔다. 지울 때는 0 을 명시해 보낸다(0117). */
  items: SaleItemInput[];
  /** 생략하면 그날 값을 그대로 둔다. 빈 배열을 보내면 전부 지운다. */
  etcItems?: EtcItem[];
  extraItems?: ExtraItem[];
  reason?: string;
}

export interface AmendPastSaleResult {
  /** 정말로 달라졌나. 같은 값을 다시 보내면 false 이고 아무 자국도 안 남는다(0148). */
  changed: boolean;
  /** 장부가 없어서 만들었나. 만들었으면 기준은 현재값이다. */
  created: boolean;
  /** **다음 저장에 되보낼 판본.** 안 바뀌었으면 그대로다. */
  revision: number;
  /** 이 장부를 몇 번 정정했나(감사용). 위 판본과 다른 값이다. */
  auditRevisionNo: number;
  /** null 없음 — 정정이 성공했다면 장부가 반드시 있다(`business_days.basis_quality` NOT NULL). */
  basisQuality: BasisQuality;
  shortages: Shortage[];
}

/**
 * 종료된 과거 영업일을 **다시 열지 않고** 고친다(기획서 §6.4).
 *
 * ⚠ 오늘·영업 중인 날은 이 문이 아니다 — 서버가 45011 로 돌려보낸다. 그건 오류가 아니라
 *   "판매 화면에서 저장하세요" 라는 뜻이므로 화면이 그렇게 안내한다.
 */
export function useAmendPastSale() {
  const qc = useQueryClient();
  const storeId = useStoreId();
  return useMutation({
    mutationFn: async (input: AmendPastSaleInput): Promise<AmendPastSaleResult> => {
      const { data, error } = await supabase.rpc('amend_ended_business_day', {
        p_store: storeId,
        p_date: input.date,
        p_base_revision: input.baseRevision,
        p_items: input.items.map((i) => ({
          recipe_id: i.recipeId,
          qty_hall: i.qtyHall,
          qty_delivery: i.qtyDelivery,
          qty_takeout: i.qtyTakeout,
          qty_waste: i.qtyWaste ?? 0,
        })),
        p_etc_items: input.etcItems
          ? input.etcItems.map((e) => ({ name: e.name, price: e.price, qty: e.qty, channel: e.channel ?? null }))
          : undefined,
        p_extra_items: input.extraItems
          ? input.extraItems.map((e) => ({ name: e.name, amount: e.amount, memo: e.memo ?? '' }))
          : undefined,
        p_reason: input.reason ?? undefined,
      });
      // ⚠ 코드를 살려 던진다(0145). 화면이 문구가 아니라 SQLSTATE 로 가른다.
      if (error) throw rpcError(error);

      const r = (data ?? {}) as unknown as Record<string, unknown>;
      // 부족분은 오류가 아니다 — 이미 팔린 것이다. `save_sale` 과 같은 모양으로 모은다.
      const out: Shortage[] = [];
      for (const res of ((r.items ?? []) as Record<string, unknown>[])) {
        const consume = (res?.consume ?? {}) as Record<string, unknown>;
        for (const sh of (consume.shortages ?? []) as Record<string, unknown>[]) {
          out.push({
            ingredientId: String(sh.ingredient_id),
            name: String(sh.name),
            needed: num(sh.needed),
            available: num(sh.available),
            shortage: num(sh.shortage),
          });
        }
      }
      /*
       * ⚠ 판단에 쓰는 값은 **계약으로** 읽는다. 예전엔 `Boolean(...)`·`num(...)` 이라
       *   서버가 빠뜨려도 `changed=false`·`revision=0` 으로 조용히 넘어갔다 —
       *   앞엣것은 "안 바뀌었어요" 라는 거짓말이고, 뒤엣것은 다음 저장을 45009 로 막는다.
       */
      return { ...parseAmendResultContract(r), shortages: out };
    },
    /*
     * 과거를 고치면 그날뿐 아니라 **그날이 든 모든 기간 집계**가 달라진다.
     * `qk.sales` 를 통째로 버린다 — 어느 기간 카드가 그 날을 품고 있는지 셀 수 없다.
     */
    onSuccess: (_r, input) => invalidate(qc, [...invalidateOn.e10(), qk.salesDay(input.date)]),
  });
}
