  ingredients: ShortageIngredient[];
}
export interface ShortageResult {
  /** 'start' 면 안전재고를, 'sale' 이면 필요 수량을 나란히 보여 준다(기획안 §4.4). */
  mode: ShortageMode;
  /**
   * 잴 수 있었나(0119). 필요량은 **그날 스냅샷**에서 오므로 영업 시작 전에는 못 잰다.
   * ⚠ false 면 `ingredientCount: 0` 은 "넉넉하다"가 아니라 **"못 쟀다"** 는 뜻이다.
   *   둘을 같이 취급하면 영업 시작 직후 재시도에서 경고가 통째로 새어 나간다.
   */
  hasBasis: boolean;
  ingredientCount: number;
  recipes: ShortageRecipe[];
}

const parseShortages = (data: unknown): ShortageResult => {
  const r = (data ?? {}) as Record<string, unknown>;
  return {
    mode: r.mode === 'sale' ? 'sale' : 'start',
    // 영업 시작 판정은 지금 재고만 보므로 언제나 잴 수 있다. 스냅샷이 필요한 건 판매 판정뿐이다.
    hasBasis: r.mode === 'sale' ? r.has_basis === true : true,
    ingredientCount: num(r.ingredient_count),
    recipes: ((r.recipes ?? []) as Record<string, unknown>[]).map((x) => ({
      recipeId: String(x.recipe_id),
      name: String(x.name),
      ingredients: ((x.ingredients ?? []) as Record<string, unknown>[]).map((g) => ({
        ingredientId: String(g.ingredient_id),
        name: String(g.name),
        baseUnit: String(g.base_unit),
        safetyStock: num(g.safety_stock),
        safetyStockIsBase: g.safety_stock_is_base === true,
        perVolume: num(g.per_volume),
        needPerServing: num(g.need_per_serving),
        need: num(g.need),
        stock: num(g.stock),
      })),
    })),
  };
};

/** 영업 시작 판정 — 지금 재고로 **1개도 못 만드는** 레시피(0107). 상단 안내도 이 숫자다. */
export function useRecipeShortages(enabled = true) {
  const storeId = useStoreId();
  return useQuery({
    queryKey: ['sales', 'shortages', storeId],
    enabled: enabled && Boolean(storeId),
    queryFn: async (): Promise<ShortageResult> => {
      const { data, error } = await supabase.rpc('recipe_shortages', { p_store: storeId });
      if (error) throw new Error(error.message);
      return parseShortages(data);
    },
  });
}

/** 저장 직전에 보낼 판매 묶음. `save_sale` 이 받는 것과 같은 모양이어야 한다. */
const toRpcItems = (items: SaleItemInput[]) =>
  items.map((i) => ({
    recipe_id: i.recipeId,
    qty_hall: i.qtyHall,
    qty_delivery: i.qtyDelivery,
    qty_takeout: i.qtyTakeout,
    qty_waste: i.qtyWaste ?? 0,
  }));

/**
 * 판매 판정 — 이 판매를 저장하면 **더 빠질 몫**이 모자란가(0107).
 *
 * ⚠ 전체 판매량이 아니라 증가분이다. 10개를 7개로 고치는데 경고가 뜨면 거짓말이다.
 *   그 계산은 전부 서버에 있다 — 여기서는 결과를 그리기만 한다.
 */
export function useSaleShortages(date: string, items: SaleItemInput[], enabled = true) {
  const storeId = useStoreId();
  return useQuery({
    queryKey: ['sales', 'saleShortages', storeId, date, toRpcItems(items)],
    enabled: enabled && Boolean(storeId) && items.length > 0,
    queryFn: async (): Promise<ShortageResult> => {
      const { data, error } = await supabase.rpc('sale_shortages', {
        p_store: storeId, p_date: date, p_items: toRpcItems(items),
      });
      if (error) throw new Error(error.message);
      return parseShortages(data);
    },
  });
}

/**
 * 영업 시작 버튼을 누른 그 순간 한 번 재는 용도.
 *
 * ⚠ 캐시(`useRecipeShortages`)를 읽으면 안 된다. 아직 안 받았거나 실패했으면
 *   `undefined` 라 `?? 0` 에 걸려 **부족이 없는 것처럼** 지나간다 — 조용히 틀리는 쪽이다.
 *   눌렀을 때 서버에 직접 물어보면 로딩이라는 상태 자체가 없다.
 */
export function useCheckRecipeShortages() {
  const storeId = useStoreId();
  return useCallback(async (): Promise<ShortageResult> => {
    const { data, error } = await supabase.rpc('recipe_shortages', { p_store: storeId });
    if (error) throw new Error(error.message);
    return parseShortages(data);
  }, [storeId]);
}

/** 저장 버튼을 누른 그 순간 한 번 재는 용도. 조회 캐시에 얹지 않는다. */
export function useCheckSaleShortages() {
  const storeId = useStoreId();
  return useCallback(
    async (date: string, items: SaleItemInput[]): Promise<ShortageResult> => {
      const { data, error } = await supabase.rpc('sale_shortages', {
        p_store: storeId, p_date: date, p_items: toRpcItems(items),
      });
      if (error) throw new Error(error.message);
      return parseShortages(data);
    },
    [storeId],
  );
}

/**
 * 단위·언어·알림·세금·영업시간처럼 여러 화면이 공유하는 매장 설정 훅.
 * 설정 응답 계약과 판본 저장은 이 경계에서만 소유한다.
 */
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { invalidate, invalidateOn, qk } from '@/lib/queryClient';
import { rpcError, supabase } from '@/lib/supabase';
import { asJson } from '@/lib/json';
import { useStoreId } from '@/lib/SessionProvider';
import type { TaxMode } from '@sikjae/types';
import { LOCALES } from '@sikjae/core';
import { rpcNumber } from '@/lib/rpcValue';

// ── 매장 설정 (MY-06 단위 · MY-08 언어/통화 · 알림) ───────────
export interface StoreSettings {
  unitSystem: string;
  cupVolume: number;
  defaultTargetProfitRate: number;
  locale: string;
  currency: string;
  unitPriceDigits: number;
  quantityDigits: number;
  moneyDigits: number;
  alertMorningSummary: boolean;
  alertInboundDelay: boolean;
  alertPriceSpike: boolean;
  alertTargetMiss: boolean;
  /** 영업 시작 시각 'HH:MM'. */
  /** ⚠ 표시 폼의 **월요일** 값이다(0156 이후 영업시간은 요일별이다). 권위는 규칙이다. */
  openTime: string;
  /** 영업 종료 시각 'HH:MM'. 시작보다 이르면 자정을 넘는 영업이다. */
  closeTime: string;
  /** 브레이크 타임(선택). 없으면 null. */
  breakStart: string | null;
  breakEnd: string | null;
  /** 자정을 넘는 영업인가 — 서버가 판단해서 준다. */
  overnight: boolean;
  /** 총 영업 시간(분). 10:00~02:00 이면 960. */
  openMinutes: number;
  /**
   * 세금 — **매장 하나에 하나다**(0087). 레시피마다 다르지 않다.
   * 고치는 길은 MY > 세금 뿐이고, 고치면 전 레시피 손익 변동에 기록된다.
   */
  taxMode: TaxMode;
  taxItems: { name: string; rate: number }[];
  /** 저장 토큰(0171) — save_settings 의 p_base_revision. 다른 기기가 먼저 저장했으면 45009. */
  revision: number;
}

/**
 * get_settings 응답 계약 — 키와 JSON 타입. 하나라도 빠지면 오류다(기본값으로 메우지 않는다).
 * ⚠ DB 시험 32 가 **실제 RPC 응답**의 키 집합을 이 목록과 같은 리터럴로 재고, 앱 시험(settingsResponse)이
 *   그 리터럴을 읽어 여기와 대조한다 — 어느 한쪽만 고치면 빨개진다(검토 P0: cup_volume 이 RPC 에 없었다).
 */
export const SETTINGS_SHAPE = {
  locale: 'string', currency: 'string', unit_system: 'string',
  cup_volume: 'number', default_target_profit_rate: 'number',
  unit_price_digits: 'number', quantity_digits: 'number', money_digits: 'number',
  alert_morning_summary: 'boolean', alert_inbound_delay: 'boolean', alert_price_spike: 'boolean', alert_target_miss: 'boolean',
  open_time: 'string', close_time: 'string', break_start: 'string|null', break_end: 'string|null',
  overnight: 'boolean', open_minutes: 'number', tax_mode: 'string', tax_items: 'array',
  revision: 'number',
} as const;

/**
 * 응답 경계 검증(검토 지적). 예전엔 `data ?? {}` 로 null 을 빈 객체로 바꾸고 ko/KRW 를 채워서,
 * 설정 행이 없거나 RLS 가 회귀해도 **정상 한국어 설정처럼** 보였다. 이제 null·키 누락·타입 불일치는
 * 오류이고, 화면은 그걸 오류로 그린다. 시험이 이 함수만 떼어 잰다.
 */
export function parseStoreSettings(data: unknown): StoreSettings {
  if (data === null || data === undefined || typeof data !== 'object' || Array.isArray(data)) {
    throw new Error('설정 응답이 비어 있어요 — 설정 행이 없거나 권한이 없어요');
  }
  const r = data as Record<string, unknown>;
  for (const [k, t] of Object.entries(SETTINGS_SHAPE)) {
    const v = r[k];
    const ok = t === 'array' ? Array.isArray(v)
      : t === 'string|null' ? (v === null || typeof v === 'string')
      : typeof v === t;
    if (!ok) throw new Error(`설정 응답에 ${k} 가 없거나 형식이 달라요 (${t})`);
  }
  /*
   * 값의 뜻(검토 P1) — 타입만 보면 미등록 언어·통화, 음수 컵, 자릿수 9, "25:00", 깨진 세금 항목이 통과하고
   * 미등록 언어는 나중에 ko 로 위장된다. 서버(0167~0169)와 같은 규칙으로 여기서도 거른다.
   */
  const bad = (k: string, why: string): never => { throw new Error(`설정 응답의 ${k} 가 이상해요: ${why}`); };
  const loc = LOCALES.find((l) => l.key === r.locale);
  if (!loc) bad('locale', `미등록 언어 ${String(r.locale)}`);
  if (r.currency !== loc!.currency) bad('currency', `${String(r.currency)} 는 ${loc!.key} 의 통화(${loc!.currency})가 아니에요`);
  if (r.money_digits !== loc!.moneyDigits) bad('money_digits', `${String(r.money_digits)} ≠ 통화 자릿수 ${loc!.moneyDigits}`);
  if (r.unit_system !== 'metric') bad('unit_system', `1차는 metric 뿐 (${String(r.unit_system)})`);
  const cup = r.cup_volume as number;
  if (!Number.isFinite(cup) || cup <= 0 || cup > 5000) bad('cup_volume', `0 < v ≤ 5000 (${cup})`);
  for (const k of ['unit_price_digits', 'quantity_digits'] as const) {
    const v = r[k] as number;
    if (!Number.isInteger(v) || v < 0 || v > 4) bad(k, `0~4 정수 (${v})`);
  }
  const rate = r.default_target_profit_rate as number;
  if (!Number.isFinite(rate) || rate < 0 || rate > 100) bad('default_target_profit_rate', `0~100 (${rate})`);
  const HHMM = /^([01]\d|2[0-3]):[0-5]\d$/;
  for (const k of ['open_time', 'close_time'] as const) if (!HHMM.test(r[k] as string)) bad(k, `HH:MM 이 아니에요 (${String(r[k])})`);
  for (const k of ['break_start', 'break_end'] as const) if (r[k] !== null && !HHMM.test(r[k] as string)) bad(k, `HH:MM 이 아니에요 (${String(r[k])})`);
  if (!Number.isInteger(r.open_minutes) || (r.open_minutes as number) < 0 || (r.open_minutes as number) > 1440) bad('open_minutes', `0~1440 (${String(r.open_minutes)})`);
  if (!TAX_MODES.has(r.tax_mode as string)) bad('tax_mode', `모르는 값 ${String(r.tax_mode)}`);
  if (!Number.isSafeInteger(r.revision) || (r.revision as number) < 1) bad('revision', `1 이상 정수 (${String(r.revision)})`);
  // 서버 assert_tax_items 와 같은 규칙 — 이름은 다듬어 비어 있지 않고, 요율은 0 이상 100 **미만**.
  for (const [i, t] of (r.tax_items as unknown[]).entries()) {
    const it = t as Record<string, unknown> | null;
    if (!it || typeof it !== 'object' || typeof it.name !== 'string' || it.name.trim() === ''
        || typeof it.rate !== 'number' || !Number.isFinite(it.rate) || it.rate < 0 || it.rate >= 100) {
      bad('tax_items', `${i}번째 항목이 {name: 비어 있지 않은 문자열, rate: 0 이상 100 미만} 이 아니에요`);
    }
  }
  return {
    unitSystem: r.unit_system as string,
    cupVolume: r.cup_volume as number,
    defaultTargetProfitRate: r.default_target_profit_rate as number,
    // core LocaleKey 다('ko', 'en-US', …). 예전 기본값 'ko-KR' 은 0168 이 'ko' 로 옮겼다.
    locale: r.locale as string,
    currency: r.currency as string,
    unitPriceDigits: r.unit_price_digits as number,
    quantityDigits: r.quantity_digits as number,
    moneyDigits: r.money_digits as number,
    alertMorningSummary: r.alert_morning_summary as boolean,
    alertInboundDelay: r.alert_inbound_delay as boolean,
    alertPriceSpike: r.alert_price_spike as boolean,
    alertTargetMiss: r.alert_target_miss as boolean,
    openTime: r.open_time as string,
    closeTime: r.close_time as string,
    breakStart: r.break_start as string | null,
    breakEnd: r.break_end as string | null,
    overnight: r.overnight as boolean,
    openMinutes: r.open_minutes as number,
    taxMode: r.tax_mode as TaxMode,
    taxItems: (r.tax_items as { name: string; rate: number }[]).map((t) => ({ name: t.name, rate: t.rate })),
    revision: r.revision as number,
  };
}
/** 서버 settings.tax_mode 의 값 집합(0090 이후 tax_of 가 읽지 않지만 응답엔 남아 있다). */
const TAX_MODES = new Set(['included', 'separate', 'exempt']);

export function useStoreSettings() {
  const storeId = useStoreId();
  return useQuery({
    queryKey: qk.storeSettings,
    queryFn: async (): Promise<StoreSettings> => {
      const { data, error } = await supabase.rpc('get_settings', { p_store: storeId });
      if (error) throw new Error(error.message);
      return parseStoreSettings(data);
    },
  });
}

/**
 * 세금 저장(0087). 전 레시피 손익이 다시 계산되고 손익 변동에 한 줄씩 남는다.
 * ⚠ 그래서 레시피·매출·수정 내역까지 함께 무효화한다 — 고정지출(E4)과 같다.
 */
export function useSaveStoreTax() {
  const qc = useQueryClient();
  const storeId = useStoreId();
  return useMutation({
    mutationFn: async (input: { items: { name: string; rate: number }[]; baseRevision: number }) => {
      if (!Number.isSafeInteger(input.baseRevision) || input.baseRevision < 1) {
        throw new Error('설정을 아직 불러오지 못했어요 — 잠시 후 다시 시도해 주세요');
      }
      const items = input.items
        // 서버 assert_tax_items 계약과 같다. 0%도 아직 요율을 정하지 않은 유효 항목으로 보존한다.
        .filter((t) => t.name.trim() !== '' && t.rate >= 0)
        .map((t) => ({ name: t.name.trim(), rate: t.rate }));
      const { data, error } = await supabase.rpc('save_store_tax', {
        p_store: storeId,
        // ⚠ 서버 인자는 남아 있지만 tax_of() 가 더는 읽지 않는다(0090).
        //   세금은 항목의 합뿐이다. 인자를 지우려면 RPC 를 drop 해야 해서 자리만 뒀다.
        p_mode: 'included',
        p_items: items,
        p_base_revision: input.baseRevision,
      });
      if (error) throw rpcError(error);
      return { ...parseTaxSaveResult(data), items };
    },
    onSuccess: (result) => {
      qc.setQueryData<StoreSettings>(qk.storeSettings, (old) => old
        ? { ...old, taxMode: 'included', taxItems: result.items, revision: result.revision }
        : old);
      invalidate(qc, [qk.storeSettings, ...invalidateOn.e4()]);
    },
  });
}

export interface SettingsSaveResult { changed: boolean; revision: number }
export interface TaxSaveResult extends SettingsSaveResult { recipes: number }

function resultObject(data: unknown, what: string): Record<string, unknown> {
  if (data === null || typeof data !== 'object' || Array.isArray(data)) {
    throw new Error(`서버가 ${what} 저장 결과를 주지 않았어요`);
  }
  return data as Record<string, unknown>;
}

function resultBool(r: Record<string, unknown>, key: string, what: string): boolean {
  if (typeof r[key] !== 'boolean') throw new Error(`서버 ${what} 결과의 ${key} 형식이 달라요`);
  return r[key] as boolean;
}

function resultInt(r: Record<string, unknown>, key: string, what: string, min: number): number {
  const v = r[key];
  if (typeof v !== 'number' || !Number.isSafeInteger(v) || v < min || v > 2147483647) {
    throw new Error(`서버 ${what} 결과의 ${key} 형식이 달라요`);
  }
  return v;
}

/** save_settings 응답 계약 — 누락을 false/0 으로 위장하지 않는다. */
export function parseSettingsSaveResult(data: unknown): SettingsSaveResult {
  const r = resultObject(data, '설정');
  return { changed: resultBool(r, 'changed', '설정'), revision: resultInt(r, 'revision', '설정', 1) };
}

/** save_store_tax 응답 계약. */
export function parseTaxSaveResult(data: unknown): TaxSaveResult {
  const r = resultObject(data, '세금');
  return {
    changed: resultBool(r, 'changed', '세금'),
    recipes: resultInt(r, 'recipes', '세금', 0),
    revision: resultInt(r, 'revision', '세금', 1),
  };
}

/**
 * 서버 save_settings(0172)와 합의한 **10개 키**. StoreSettings 의 나머지(taxItems·taxMode·
 * overnight·영업시간…)는 타입에서부터 못 넘긴다 — 예전엔 넓은 타입이 받아 놓고 전송에서
 * 버려서 빈 저장이 성공처럼 끝났다(검토 지적).
 */
export type SaveSettingsInput = Pick<StoreSettings,
  | 'locale' | 'unitSystem' | 'cupVolume' | 'defaultTargetProfitRate'
  | 'unitPriceDigits' | 'quantityDigits'
  | 'alertMorningSummary' | 'alertInboundDelay' | 'alertPriceSpike' | 'alertTargetMiss'>;
// ⚠ currency·moneyDigits 는 여기 없다 — **언어가 정한다**(0168 locale_defaults). 서버가 파생하고,
//   같은 요청에 다른 값이 실리면 거부한다. 앱은 locale 만 보낸다.

const SETTINGS_KEYS: Record<keyof SaveSettingsInput, string> = {
  locale: 'locale',
  unitSystem: 'unit_system',
  cupVolume: 'cup_volume',
  defaultTargetProfitRate: 'default_target_profit_rate',
  unitPriceDigits: 'unit_price_digits',
  quantityDigits: 'quantity_digits',
  alertMorningSummary: 'alert_morning_summary',
  alertInboundDelay: 'alert_inbound_delay',
  alertPriceSpike: 'alert_price_spike',
  alertTargetMiss: 'alert_target_miss',
};

/**
 * 전송 페이로드 — 합의한 키만 싣고, **실을 게 없으면 오류**다(조용한 no-op 금지).
 * ⚠ 영업시간은 여기로 안 간다(0163) — MY > 영업시간의 set_operating_hours(판본 필수)가 유일한 문이다.
 */
export function buildSettingsPayload(input: Partial<SaveSettingsInput>): Record<string, unknown> {
  const payload: Record<string, unknown> = {};
  for (const k of Object.keys(SETTINGS_KEYS) as (keyof SaveSettingsInput)[]) {
    const v = input[k];
    if (v !== undefined) payload[SETTINGS_KEYS[k]] = v;
  }
  if (Object.keys(payload).length === 0) throw new Error('저장할 설정 값이 없어요');
  return payload;
}

/**
 * 설정 저장 — **판본 토큰**(0171)을 함께 보낸다. 마지막으로 받은 설정의 revision 이 base 이고, 그 사이
 * 다른 기기가 저장했으면 서버가 45009 로 거절한다(화면은 코드로 갈라 충돌 배너를 띄운다).
 * 화면이 편집 시작 판본을 주지 않으면 보내지 않는다 — base 없이 보내면 서버가 BASE_REQUIRED 로 막는다.
 */
export interface SaveSettingsMutation {
  values: Partial<SaveSettingsInput>;
  /** 사용자가 편집을 시작했을 때의 판본. 저장 직전 최신 캐시로 바꾸면 낡은 초안이 덮어쓴다. */
  baseRevision: number;
}

export function useSaveSettings() {
  const qc = useQueryClient();
  const storeId = useStoreId();
  return useMutation({
    mutationFn: async (input: SaveSettingsMutation) => {
      if (!Number.isSafeInteger(input.baseRevision) || input.baseRevision < 1) throw new Error('설정을 아직 불러오지 못했어요 — 잠시 후 다시 시도해 주세요');
      const { data, error } = await supabase.rpc('save_settings', {
        p_store: storeId, p_payload: asJson(buildSettingsPayload(input.values)), p_base_revision: input.baseRevision,
      });
      // ⚠ 코드를 살려 던진다 — 화면이 45009(다른 기기 변경)를 문구가 아니라 코드로 가른다.
      if (error) throw rpcError(error);
      return parseSettingsSaveResult(data);
    },
    onSuccess: (result, input) => {
      // 새 판본을 즉시 올려 재조회 전 연속 저장이 방금 자기가 올린 판본과 충돌하지 않게 한다.
      qc.setQueryData<StoreSettings>(qk.storeSettings, (old) => {
        if (!old) return old;
        const next = { ...old, ...input.values, revision: result.revision };
        if (input.values.locale !== undefined) {
          const loc = LOCALES.find((l) => l.key === input.values.locale);
          if (loc) { next.currency = loc.currency; next.moneyDigits = loc.moneyDigits; }
        }
        return next;
      });
      invalidate(qc, [qk.settings, qk.storeSettings]);
    },
    // 45009 뒤에는 최신값을 받되, 화면은 사용자가 새로고침하기 전까지 자기 초안을 유지하고 저장을 막는다.
    onError: () => invalidate(qc, [qk.settings, qk.storeSettings]),
  });
}

export interface OperatingHours {
  openTime: string;
  closeTime: string;
  breakStart: string | null;
  breakEnd: string | null;
  /** 종료가 시작보다 이르면 1 — 다음 날로 넘어간다는 뜻이다. 서버가 계산한다. */
  closeDayOffset: number;
  closed: boolean;
}

export interface HoursStatus {
  localDate: string;
  /** 매장 시간대(IANA). 정한 적 없으면 서버 기본(Asia/Seoul)이 온다. */
  timezone: string;
  /** 사장님이 **정한** 값인가(0122 confirmed). false 면 화면이 기기 시간대를 제안한다. */
  timezoneConfirmed: boolean;
  /** 오늘 **실제로** 적용 중인 시간. settings 입력값이 아니라 규칙에서 온다. */
  today: OperatingHours;
  /** 지금 적용 중인 규칙 전체(주간). 규칙이 없으면 null. */
  currentRule: WeeklyRuleInfo | null;
  /**
   * 아직 시작 안 한 규칙. 없으면 null.
   * ⚠ 있으면 **이게 편집 기준이다**(0159 · 검토 P1-1) — 예약 주간표를 통째로 받아
   *   이어서 편집해야 한다. 예전엔 그날 시간만 받아서, 재진입한 화면이 현재 규칙으로
   *   다시 편집했고 예약 변경이 조용히 사라졌다.
   */
  pending: (WeeklyRuleInfo & { effectiveFrom: string; hours: OperatingHours }) | null;
}

/** 편집 기준 규칙 — 판본(revision)은 저장에 되보내는 토큰이다(0159). */
export interface WeeklyRuleInfo {
  ruleId: string;
  revision: number;
  effectiveFrom: string | null;
  weeklyHours: Record<string, unknown>;
  weeklyBreaks: Record<string, unknown>;
}

const HHMM = /^([01]\d|2[0-3]):[0-5]\d(:[0-5]\d)?$/;
const YMD_RE = /^\d{4}-(0[1-9]|1[0-2])-(0[1-9]|[12]\d|3[01])$/;

const failed = (what: string) =>
  new Error(`서버가 ${what}을 주지 않았어요. 잠시 후 다시 시도해 주세요`);

/** 시각 문자열. 형식이 아니면 던진다 — 빈 문자열로 넘기면 화면이 `~` 만 그린다. */
function reqTime(v: unknown, what: string): string {
  const t = typeof v === 'string' ? v : '';
  if (!HHMM.test(t)) throw failed(what);
  return t;
}

/** 브레이크는 **없는 게 정상**이다. 다만 있으면 시각이어야 한다. */
function optTime(v: unknown, what: string): string | null {
  if (v === null || v === undefined) return null;
  return reqTime(v, what);
}

/**
 * ⚠ 조용한 기본값을 두지 않는다(0132). `String(v.open_time ?? '')` 이면 서버가 키를
 *   빠뜨려도 화면이 멀쩡히 열리고 시간만 빈칸이 된다. 사장님은 영업시간이 지워진 줄 안다.
 */
const hoursOf = (v: Record<string, unknown>, where: string): OperatingHours => ({
  openTime: reqTime(v.open_time, `${where} 시작 시각`),
  closeTime: reqTime(v.close_time, `${where} 종료 시각`),
  breakStart: optTime(v.break_start, `${where} 브레이크 시작`),
  breakEnd: optTime(v.break_end, `${where} 브레이크 종료`),
  closeDayOffset: rpcNumber(v.close_day_offset),
  closed: Boolean(v.closed),
});

/**
 * 지금 적용 중인 영업시간과 **예약된** 영업시간(0131).
 *
 * ⚠ 왜 `useStoreSettings` 로 안 되는가 — 그건 **입력 폼**이라 저장하는 순간 새 값이 된다.
 *   그런데 영업 중에 바꾸면 실제 적용은 **다음 영업일**부터다(0130). 둘을 같은 값으로
 *   보여 주면 화면이 "오늘부터 바뀌었다"고 거짓말한다.
 */
export function useHoursStatus() {
  const storeId = useStoreId();
  return useQuery({
    queryKey: [...qk.storeSettings, 'hours-status'],
    enabled: Boolean(storeId),
    queryFn: async (): Promise<HoursStatus> => {
      const { data, error } = await supabase.rpc('operating_hours_status', { p_store: storeId });
      if (error) throw new Error(error.message);
      const r = (data ?? {}) as unknown as Record<string, unknown>;

      const localDate = typeof r.local_date === 'string' ? r.local_date : '';
      if (!YMD_RE.test(localDate)) throw failed('오늘 날짜');

      // ⚠ 조용한 기본값 금지(0132·0156). 없으면 던져야 배포 어긋남이 화면에 보인다.
      const timezone = typeof r.timezone === 'string' && r.timezone !== '' ? r.timezone : null;
      if (timezone === null) throw failed('매장 시간대');
      if (typeof r.timezone_confirmed !== 'boolean') throw failed('시간대 확정 여부');

      const ruleInfo = (v: unknown, what: string): WeeklyRuleInfo | null => {
        const rr = v as Record<string, unknown> | null | undefined;
        if (!rr) return null;
        const wh = rr.weekly_hours;
        const wb = rr.weekly_breaks;
        if (typeof wh !== 'object' || wh === null || typeof wb !== 'object' || wb === null) {
          throw failed(what);
        }
        // ⚠ 판본이 없으면 던진다 — 0 으로 메우면 저장이 45009 로 막힌다(dayContract 와 같은 이유).
        const rid = typeof rr.rule_id === 'string' && rr.rule_id !== '' ? rr.rule_id : null;
        const rev = typeof rr.revision === 'number' && Number.isSafeInteger(rr.revision) && rr.revision >= 1
          ? rr.revision : null;
        if (rid === null || rev === null) throw failed(`${what} 판본`);
        return {
          ruleId: rid, revision: rev,
          effectiveFrom: typeof rr.effective_from === 'string' && YMD_RE.test(rr.effective_from)
            ? rr.effective_from : null,
          weeklyHours: wh as Record<string, unknown>,
          weeklyBreaks: wb as Record<string, unknown>,
        };
      };
      const currentRule = ruleInfo(r.current_rule, '주간 규칙');

      const today = r.today as Record<string, unknown> | null;
      if (!today) throw failed('오늘 영업시간');

      const p = r.pending as Record<string, unknown> | null;
      let pending: HoursStatus['pending'] = null;
      if (p) {
        const info = ruleInfo(p, '예약 규칙');
        const from = info?.effectiveFrom ?? null;
        if (info === null || from === null) throw failed('영업시간 적용 시작일');
        pending = {
          ...info,
          effectiveFrom: from,
          hours: hoursOf((p.hours ?? {}) as Record<string, unknown>, '예약된'),
        };
      }

      return {
        localDate, timezone, timezoneConfirmed: r.timezone_confirmed,
        today: hoursOf(today, '오늘'), currentRule, pending,
      };
    },
  });
}

/**
 * 요일별 영업시간 저장(0156) — `set_operating_hours` 직행.
 *
 * ⚠ `useSaveSettings` 가 아니다. 그쪽(settings)은 요일 구분이 없는 옛 입력 폼이라
 *   월~일 공통값만 실을 수 있다. 요일별 규칙은 이 문으로만 온전히 간다.
 */
export function useSetOperatingHours() {
  const qc = useQueryClient();
  const storeId = useStoreId();
  return useMutation({
    mutationFn: async (input: {
      weeklyHours: Record<string, unknown>;
      weeklyBreaks: Record<string, unknown>;
      /** 편집 기준(0159). **필수**다(0163) — 서버도 없으면 거부한다(BASE_REQUIRED). */
      baseRuleId: string;
      baseRevision: number;
    }): Promise<{ effectiveFrom: string; appliesToday: boolean; ruleId: string; ruleRevision: number }> => {
      const { data, error } = await supabase.rpc('set_operating_hours', {
        p_store: storeId,
        p_weekly_hours: asJson(input.weeklyHours),
        p_weekly_breaks: asJson(input.weeklyBreaks),
        p_base_rule_id: input.baseRuleId,
        p_base_revision: input.baseRevision,
      });
      // ⚠ 코드를 살려 던진다(0145) — 화면이 45009(다른 기기 변경)를 문구가 아니라 코드로 가른다.
      if (error) throw rpcError(error);
      const r = (data ?? {}) as unknown as Record<string, unknown>;
      // 언제부터인지는 화면이 반드시 말해야 한다(0130) — 없으면 계약 위반이다.
      const from = typeof r.effective_from === 'string' ? r.effective_from : '';
      if (!YMD_RE.test(from)) throw failed('적용 시작일');
      if (typeof r.applies_today !== 'boolean') throw failed('오늘 적용 여부');
      // 다음 저장에 되보낼 판본(0159) — 없으면 계약 위반이다.
      const rid = typeof r.rule_id === 'string' && r.rule_id !== '' ? r.rule_id : null;
      const rev = typeof r.rule_revision === 'number' && Number.isSafeInteger(r.rule_revision) && r.rule_revision >= 1
        ? r.rule_revision : null;
      if (rid === null || rev === null) throw failed('규칙 판본');
      return { effectiveFrom: from, appliesToday: r.applies_today, ruleId: rid, ruleRevision: rev };
    },
    // 영업시간은 상태 카드(business_day_state)에도 실린다 — 같이 다시 그린다.
    onSuccess: () => invalidate(qc, [...invalidateOn.settingsSaved(), ...invalidateOn.businessDay()]),
  });
}

/**
 * 매장 시간대 변경(0156) — 유일한 문. 영업 중이면 서버가 45011 로 거부한다.
 * 최초 제안은 화면이 기기 시간대(Intl)로 하고, 확정은 이 RPC 가 confirmed 로 남긴다.
 */
export function useSetStoreTimezone() {
  const qc = useQueryClient();
  const storeId = useStoreId();
  return useMutation({
    mutationFn: async (timezone: string): Promise<void> => {
      const { error } = await supabase.rpc('set_store_timezone', {
        p_store: storeId, p_timezone: timezone,
      });
      if (error) throw new Error(error.message);
    },
    // 시간대가 바뀌면 '오늘'이 움직인다 — 날짜를 쓰는 화면 전부가 대상이다.
    onSuccess: () => invalidate(qc, [...invalidateOn.settingsSaved(), ...invalidateOn.businessDay()]),
  });
}

-- ════════════════════════════════════════════════════════════════
-- 31 · settings 직접 쓰기 봉쇄 (0164) — 판본 우회의 마지막 문
--
-- 실측된 우회: 인증 사용자가 settings 를 직접 고치면 동기화 트리거가 영업시간을
-- 규칙에 옮기면서 revision 은 안 올렸다(09:00–21:00 · rev 1 → 03:00–04:00 · rev 1).
-- 이제 settings 는 앱 롤이 읽기만 하고, 쓰기는 definer RPC 둘(save_settings ·
-- save_store_tax)뿐이며, 동기화 트리거는 없다 — 표시 폼이 규칙에 닿을 길이 없다.
-- ════════════════════════════════════════════════════════════════

do $t$
declare
  v_store uuid := pg_temp.store();
  v_rule0 record;
  v_rule1 record;
begin
  select id, revision, weekly_hours into v_rule0
    from operating_rules where store_id = v_store and effective_to is null;

  -- ① 앱 롤의 직접 DML 은 권한부터 없다.
  perform pg_temp.raises('settings UPDATE 는 42501',
    format($q$update settings set open_time = '03:00', close_time = '04:00' where store_id = %L$q$, v_store), '42501');
  perform pg_temp.raises('settings INSERT 도 42501',
    format($q$insert into settings (store_id) values (%L) on conflict do nothing$q$, v_store), '42501');
  perform pg_temp.raises('settings DELETE 도 42501',
    format($q$delete from settings where store_id = %L$q$, v_store), '42501');

  /*
   * ①-b 트리거·참조도 없다(0165). 0164 는 INSERT/UPDATE/DELETE 만 걷어내서 `rxt` 가
   *     남았고, 인증 롤이 실제로 트리거를 붙일 수 있었다 — 그 트리거는 definer RPC 가
   *     그 테이블을 쓸 때도 발동해 정상 저장을 멈춘다.
   * ⚠ 트리거 함수는 **소유자로** 미리 만든다. 안 그러면 함수 생성(스키마 CREATE 권한)에서
   *   먼저 막혀 "트리거를 못 만든다"를 잘못 증명한다 — 실제로 그렇게 착각했다.
   */
  set local role postgres;
  execute $f$create or replace function pg_temp_probe_trg() returns trigger language plpgsql as $b$ begin return new; end $b$$f$;
  set local role authenticated;
  perform pg_temp.raises('settings 에 트리거를 못 붙인다',
    'create trigger probe_trg before update on public.settings for each row execute function pg_temp_probe_trg()', '42501');
  perform pg_temp.raises('operating_rules 에도 못 붙인다',
    'create trigger probe_trg2 before update on public.operating_rules for each row execute function pg_temp_probe_trg()', '42501');
  perform pg_temp.raises('쓰기가 열린 테이블(recipes)에도 못 붙인다',
    'create trigger probe_trg3 before update on public.recipes for each row execute function pg_temp_probe_trg()', '42501');
  perform pg_temp.ok('어떤 테이블에도 TRIGGER/REFERENCES 가 없다',
    (select count(*) from pg_class c join pg_namespace n on n.oid = c.relnamespace
      where n.nspname = 'public' and c.relkind = 'r'
        and (has_table_privilege('authenticated', c.oid, 'TRIGGER')
             or has_table_privilege('authenticated', c.oid, 'REFERENCES'))) = 0);
  -- ② 그래도 읽기는 된다 — 화면이 표시 폼을 읽는다.
  perform pg_temp.ok('settings 읽기는 된다',
    exists (select 1 from settings where store_id = v_store));

  -- ③ 규칙·판본은 그대로다 — 우회가 실제로 막혔다는 증거.
  select id, revision, weekly_hours into v_rule1
    from operating_rules where store_id = v_store and effective_to is null;
  perform pg_temp.ok('규칙 행이 그대로', v_rule1.id = v_rule0.id);
  perform pg_temp.ok('판본이 그대로', v_rule1.revision = v_rule0.revision);
  perform pg_temp.ok('시간표가 그대로', v_rule1.weekly_hours = v_rule0.weekly_hours);

  -- ④ 쓰기 RPC 는 살아 있다(definer) — 설정은 여전히 저장된다.
  -- 금액 자릿수는 통화가 정한다(0168) — 사장님이 고치는 자릿수는 수량 쪽이다.
  perform save_settings(v_store, jsonb_build_object('quantity_digits', 2), pg_temp.settings_rev(v_store));
  perform pg_temp.eq_t('save_settings 는 definer 로 통과', (select quantity_digits::text from settings where store_id = v_store), '2');
  perform save_store_tax(v_store,
    (select tax_mode from settings where store_id = v_store),
    (select coalesce(tax_items, '[]'::jsonb) from settings where store_id = v_store),
    pg_temp.settings_rev(v_store));
  perform pg_temp.ok('save_store_tax 도 definer 로 통과', true);

  -- ⑤ 동기화 트리거가 없다 — 소유자가 표시 폼을 바꿔도 규칙은 안 움직인다.
  perform pg_temp.ok('동기화 트리거가 없다',
    not exists (select 1 from pg_trigger where tgname = 'settings_sync_operating_rule_trg'));
  set local role postgres;
  update settings set open_time = '03:00', close_time = '04:00' where store_id = v_store;
  set local role authenticated;
  select id, revision, weekly_hours into v_rule1
    from operating_rules where store_id = v_store and effective_to is null;
  perform pg_temp.ok('표시 폼을 바꿔도 규칙 시간표는 그대로 — 실측 우회가 닫혔다',
    v_rule1.weekly_hours = v_rule0.weekly_hours and v_rule1.revision = v_rule0.revision);

  -- ⑥ 정식 문으로 바꾸면 판본이 오른다.
  perform pg_temp.set_hours(
    (select jsonb_object_agg(d::text, jsonb_build_object('open','10:00','close','20:00')) from generate_series(0, 6) d));
  perform pg_temp.ok('정식 문은 판본을 올린다',
    (select max(revision) from operating_rules where store_id = v_store) > v_rule0.revision
    or (select count(*) from operating_rules where store_id = v_store) > 1);
end $t$;
-- ── 신규 매장 초기화 (0165) ─────────────────────────────────────
/*
 * 실측된 깨짐: 인증 롤이 stores 에 직접 insert 하면 시간대 트리거가 definer 가 아니라
 * 42501 로 매장 생성 자체가 죽었고, 통과해도 settings 행이 없어 save_store_tax 가
 * `update 0행` 에 changed=true 를 돌려줬다. 기본 영업시간도 규칙 09–21 vs 표시 11–22 로 갈렸다.
 */
do $t$
declare
  v_id    uuid;
  v_res   jsonb;
  v_other uuid;
  v_owner uuid := pg_temp.new_owner();   -- 계정당 매장 하나(0167) — 새 사장님
begin
  -- ① 소유자 픽스처 생성에도 트리거 셋이 따라붙는다. 앱 롤의 직접 INSERT 는 0167 로 없어졌다 —
  --    그 계약은 아래 '단일 매장' 블록이 잰다.
  set local role postgres;
  insert into stores (owner_id, name) values (v_owner, '시험 매장 신규직접')
    returning id into v_id;
  set local role authenticated;
  perform pg_temp.as_owner(v_owner);   -- 이 매장의 사장님으로 세금을 저장한다
  perform pg_temp.eq('직접 생성: 설정 행이 생긴다',
    (select count(*) from settings where store_id = v_id), 1, 0);
  perform pg_temp.eq('직접 생성: 시간대 행이 생긴다',
    (select count(*) from store_time_settings where store_id = v_id), 1, 0);
  perform pg_temp.eq('직접 생성: 영업규칙이 생긴다',
    (select count(*) from operating_rules where store_id = v_id), 1, 0);
  perform pg_temp.eq_t('기본 영업시간은 표시 폼과 같은 11:00~22:00',
    (store_hours_on(v_id, store_local_date(v_id))->>'open_time') || '~' ||
    (store_hours_on(v_id, store_local_date(v_id))->>'close_time'), '11:00:00~22:00:00');
  perform pg_temp.eq_t('규칙과 표시 폼이 안 갈린다',
    (select open_time::text || '~' || close_time::text from settings where store_id = v_id),
    '11:00:00~22:00:00');
  -- ② 세금 저장이 실제로 저장된다 — 0행에 성공을 돌려주지 않는다.
  v_res := save_store_tax(v_id, (select tax_mode from settings where store_id = v_id),
                          '[{"name":"부가세","rate":9.0909}]'::jsonb,
                          pg_temp.settings_rev(v_id));
  perform pg_temp.ok('세금 저장이 changed 를 답한다', v_res ? 'changed');
  perform pg_temp.eq('저장된 세금 항목이 실제로 있다',
    (select jsonb_array_length(tax_items) from settings where store_id = v_id), 1, 0);
  /*
   * ③ 공식 문(create_store) — 1차 범위는 매장 하나라, 이미 있으면 **그 매장**을 답하고
   *   시간대도 안 만진다(0166·0167). 그래서 새 매장의 시간대 계약은 **매장이 없는 계정**으로
   *   잰다 — 기존 사장님으로 부르면 created=false 에 기존 시간대가 온다(아래 '단일 매장' 블록).
   * ⚠ 여기서 개수 합(3)으로 재면 안 된다. 이 파일 앞 블록이 예약 규칙을 만들어 두면
   *   규칙이 2개라 합이 4가 된다 — 실제로 그렇게 빨개졌다. 있음/없음으로 잰다.
   */
  v_other := pg_temp.new_owner();
  set local role postgres;
  perform set_config('request.jwt.claims', json_build_object('sub', v_other, 'role', 'authenticated')::text, true);
  set local role authenticated;
  -- 이름 검사는 **만들 때** 한다 — 매장이 이미 있으면 이름은 쓰이지 않고 그 매장이 온다.
  perform pg_temp.raises('공식 문: 이름이 비면 거부', $q$select create_store('   ')$q$, '22000');
  v_res := create_store('시험 매장 공식문', 'America/New_York');
  v_id := (v_res->>'store_id')::uuid;
  perform pg_temp.ok('공식 문: 새 계정이면 created=true', (v_res->>'created')::boolean is true);
  perform pg_temp.eq_t('공식 문: 시간대가 정해진다', v_res->>'timezone', 'America/New_York');
  perform pg_temp.ok('공식 문: 설정·규칙·시간대가 모두 있다',
    exists (select 1 from settings where store_id = v_id)
    and exists (select 1 from operating_rules where store_id = v_id)
    and exists (select 1 from store_time_settings where store_id = v_id));
  perform pg_temp.ok('공식 문: 정한 시간대는 confirmed 다',
    (select confirmed from store_time_settings where store_id = v_id));
  perform pg_temp.ok('공식 문: 매장이 있으면 빈 이름도 그 매장을 답한다(이름은 만들 때만 본다)',
    ((create_store('   '))->>'store_id')::uuid = v_id);
  set local role postgres;
  perform set_config('request.jwt.claims', json_build_object('sub', pg_temp.owner(), 'role', 'authenticated')::text, true);
  set local role authenticated;
end $t$;


-- ── TRUNCATE 와 미래 테이블 (0166) ──────────────────────────────
/*
 * 실측된 구멍: 28개 중 23개에서 인증·익명 롤이 TRUNCATE 를 쓸 수 있었다.
 * **RLS 는 TRUNCATE 에 적용되지 않는다** — 남의 매장 행까지 통째로 사라진다
 * (검토자가 price_trends 100건 → 0건을 재현). 그리고 회수는 그때 있던 테이블에만
 * 걸리므로, 기본 권한을 안 바꾸면 다음에 만든 테이블이 다시 열린다.
 */
do $t$
declare v_n int;
begin
  perform pg_temp.raises('앱 롤은 TRUNCATE 를 못 한다',
    'truncate table public.price_trends', '42501');
  perform pg_temp.ok('어떤 테이블에도 TRUNCATE 가 없다(인증·익명)',
    (select count(*) from pg_class c join pg_namespace n on n.oid = c.relnamespace
      where n.nspname = 'public' and c.relkind = 'r'
        and (has_table_privilege('authenticated', c.oid, 'TRUNCATE')
             or has_table_privilege('anon', c.oid, 'TRUNCATE'))) = 0);

  -- 미래 테이블도 닫힌 채 태어난다 — 기본 권한(alter default privileges)이 걸렸는가.
  set local role postgres;
  create table public._probe_future_acl (id int);
  set local role authenticated;
  perform pg_temp.ok('새로 만든 테이블도 TRUNCATE/TRIGGER/REFERENCES 가 닫혀 있다',
    not has_table_privilege('authenticated', 'public._probe_future_acl', 'TRUNCATE')
    and not has_table_privilege('authenticated', 'public._probe_future_acl', 'TRIGGER')
    and not has_table_privilege('authenticated', 'public._probe_future_acl', 'REFERENCES'));
  set local role postgres;
  drop table public._probe_future_acl;
  set local role authenticated;
end $t$;


-- ── 단일 매장 계약과 백필 보존 (0166) ───────────────────────────
do $t$
declare
  v_owner_bf uuid;
  v_a jsonb; v_b jsonb;
  v_n int;
  v_store uuid;
begin
  /*
   * 두 번 눌러도 매장은 하나다(기획서 §12). 예전엔 둘이 생겼고, 앱은 정렬 없이 첫 행을
   * 골라 어느 쪽이 잡힐지 실행마다 달랐다.
   * ⚠ 시드 사장님은 이미 매장이 있다 — 그래서 첫 호출부터 created=false 여야 한다.
   */
  select count(*) into v_n from stores where owner_id = pg_temp.owner();
  v_a := create_store('중복 시험 매장');
  v_b := create_store('중복 시험 매장 2');
  perform pg_temp.eq('두 번 불러도 매장 수가 안 는다',
    (select count(*) from stores where owner_id = pg_temp.owner()), v_n, 0);
  perform pg_temp.eq_t('둘 다 같은 매장을 답한다', v_a->>'store_id', v_b->>'store_id');
  perform pg_temp.ok('이미 있으면 created=false', (v_a->>'created')::boolean is false);
  perform pg_temp.eq_t('앱과 같은 기준(created_at, id)으로 고른다',
    v_a->>'store_id',
    (select id::text from stores where owner_id = pg_temp.owner() order by created_at, id limit 1));

  /*
   * 백필 보존 — 표시 폼이 06:00–14:00 인 매장의 규칙을 11–22 로 덮으면 안 된다.
   * 문(0159)을 안 지난 규칙(revision=1)만 표시 폼을 따른다.
   */
  v_owner_bf := pg_temp.new_owner();   -- 계정당 매장 하나(0167)
  set local role postgres;
  insert into stores (owner_id, name) values (v_owner_bf, '백필 시험 매장') returning id into v_store;
  update settings set open_time = '06:00', close_time = '14:00' where store_id = v_store;
  delete from operating_rules where store_id = v_store;
  insert into operating_rules (store_id, effective_from, effective_to, weekly_hours, weekly_breaks)
       values (v_store, '-infinity', null,
               (select jsonb_object_agg(d::text, jsonb_build_object('open','11:00','close','22:00','closed',false))
                  from generate_series(0, 6) d), '{}'::jsonb);
  -- 0166 의 백필과 같은 문장(마이그레이션이 한 일을 여기서 재현해 잰다).
  update operating_rules r
     set weekly_hours = (select jsonb_object_agg(d::text, jsonb_build_object(
                                  'open', s.open_time::text, 'close', s.close_time::text,
                                  'closed', coalesce((r.weekly_hours -> d::text ->> 'closed')::boolean, false)))
                           from generate_series(0, 6) d)
    from settings s
   where s.store_id = r.store_id and r.store_id = v_store
     and r.effective_to is null and r.revision = 1
     and (r.weekly_hours -> '1' ->> 'open') is distinct from s.open_time::text;
  set local role authenticated;
  perform pg_temp.as_owner(v_owner_bf);   -- 그 매장은 다른 사장님 것 — 그 사장님으로 읽는다(RLS)
  perform pg_temp.eq_t('백필이 표시 폼(06:00~14:00)을 보존한다',
    (store_hours_on(v_store, store_local_date(v_store))->>'open_time') || '~' ||
    (store_hours_on(v_store, store_local_date(v_store))->>'close_time'), '06:00:00~14:00:00');
  perform pg_temp.as_owner(pg_temp.owner());
end $t$;


-- ── 단일 매장을 DB 가 지킨다 · create_store 재호출 무해 (0167) ────
do $t$
declare
  v_res jsonb;
  v_tz0 text;
  v_other uuid;
begin
  -- ① 재호출은 시간대를 안 바꾼다 — 열린 장부의 날짜와 현지 날짜가 갈라지면 안 된다(실측).
  perform pg_temp.open_today();   -- 영업 중이면 set_store_timezone 도 45011 인 상태
  v_tz0 := store_timezone(pg_temp.store());
  v_res := create_store('재호출', 'America/New_York');
  perform pg_temp.ok('있으면 created=false', (v_res->>'created')::boolean is false);
  perform pg_temp.eq_t('재호출은 시간대를 안 바꾼다', store_timezone(pg_temp.store()), v_tz0);
  perform pg_temp.eq_t('응답 시간대도 기존 값', v_res->>'timezone', v_tz0);

  -- ② 앱 롤의 stores 직접 쓰기는 권한부터 없다 — 매장은 create_store 로만 생긴다.
  --    RLS 만으로 막혀도 42501 이라 권한 자체를 따로 잰다(정책이 아니라 GRANT 가 닫혀야 한다).
  perform pg_temp.ok('stores 에 앱 롤 INSERT/UPDATE/DELETE GRANT 가 없다',
    not has_table_privilege('authenticated', 'public.stores', 'INSERT')
    and not has_table_privilege('authenticated', 'public.stores', 'UPDATE')
    and not has_table_privilege('authenticated', 'public.stores', 'DELETE')
    and not has_table_privilege('anon', 'public.stores', 'INSERT'));
  perform pg_temp.raises('stores 직접 INSERT 는 42501',
    format($q$insert into stores (owner_id, name) values (%L, '직접')$q$, pg_temp.owner()), '42501');
  perform pg_temp.raises('stores 직접 UPDATE 도 42501',
    format($q$update stores set name = 'x' where id = %L$q$, pg_temp.store()), '42501');
  perform pg_temp.raises('stores 직접 DELETE 도 42501',
    format($q$delete from stores where id = %L$q$, pg_temp.store()), '42501');

  -- ③ 계정당 하나 — UNIQUE(owner_id). 소유자 직접 INSERT 로도 두 번째 매장은 안 생긴다.
  --    (첫 판은 exists 트리거 + 세션 플래그였고 두 세션 동시 INSERT 가 둘 다 통과했다 — 검토 재현.)
  set local role postgres;
  perform pg_temp.raises('같은 계정의 두 번째 매장은 23505 (UNIQUE)',
    format($q$insert into stores (owner_id, name) values (%L, '둘째')$q$, pg_temp.owner()), '23505');
  set local role authenticated;
  perform pg_temp.ok('stores.owner_id 에 UNIQUE 제약이 있다 — 트리거가 아니라 제약이다',
    exists (select 1 from pg_constraint c
             where c.conrelid = 'public.stores'::regclass and c.contype = 'u'
               and c.conkey = array[(select attnum from pg_attribute
                                      where attrelid = 'public.stores'::regclass and attname = 'owner_id')]));
  perform pg_temp.ok('시험용 우회(트리거·플래그)가 운영 스키마에 없다',
    not exists (select 1 from pg_trigger where tgname = 'stores_00_single_per_owner')
    and not exists (select 1 from pg_proc where proname = 'stores_single_per_owner'));

  -- ④ 다른 사장님은 제 매장 하나를 create_store 로 만든다 — 남남 시나리오의 기반.
  v_other := pg_temp.new_owner();
  set local role postgres;
  perform set_config('request.jwt.claims', json_build_object('sub', v_other, 'role', 'authenticated')::text, true);
  set local role authenticated;
  v_res := create_store('남의 매장');
  perform pg_temp.ok('남의 계정은 새 매장을 만든다', (v_res->>'created')::boolean is true);
  set local role postgres;
  perform set_config('request.jwt.claims', json_build_object('sub', pg_temp.owner(), 'role', 'authenticated')::text, true);
  set local role authenticated;
end $t$;


-- ── 기본 권한 — postgres 와 supabase_admin 둘 다 닫혀 있다 (0166·0167) ──
/*
 * 검토 재현: supabase_admin 이 public 에 만든 테이블은 TRUNCATE/TRIGGER/REFERENCES 가 다시
 * 열렸다. postgres 는 그 롤의 기본 권한을 못 바꾸므로(멤버가 아니다) fresh-db.sh 가
 * 슈퍼유저 연결로 걷어낸다. 여기서는 **두 롤의 pg_default_acl** 을 잰다 — 표 하나 만들어
 * 보는 것은 postgres 만 할 수 있어(31 앞 블록), 나머지는 기본 권한 행 자체가 증거다.
 */
do $t$
declare v_open text;
begin
  select string_agg(r.rolname, ', ') into v_open
    from pg_default_acl a join pg_roles r on r.oid = a.defaclrole
   where a.defaclnamespace = 'public'::regnamespace and a.defaclobjtype = 'r'
     and r.rolname in ('postgres', 'supabase_admin')
     -- aclitem 글자: D=TRUNCATE t=TRIGGER x=REFERENCES. 앱 롤 항목에 하나라도 있으면 열린 것.
     and exists (select 1 from unnest(a.defaclacl) x
                  where x::text ~ '^(anon|authenticated)=' and x::text ~ '=[^/]*[Dtx]');
  /*
   * ⚠ "행이 있다"로 재지 않는다 — 새 DB 는 supabase_admin 의 기본 권한이 애초에 비어 있어
   *   회수가 무행(no-op)이고 pg_default_acl 에 행이 안 생긴다(실측). 열린 행이 **없음**이 계약이다.
   *   supabase_admin 으로 표를 실제로 만들어 보는 시험은 fresh-db.sh 의 슈퍼유저 단계가 한다
   *   (이 세션은 postgres 라 그 롤이 못 된다).
   */
  perform pg_temp.ok('postgres·supabase_admin 기본 권한에 TRUNCATE/TRIGGER/REFERENCES 가 없다',
    v_open is null);
end $t$;


-- ── save_settings 계약 (0167) — 받는 키는 저장되고, 모르는 키는 거부 ──
do $t$
begin
  -- 전제: 이 블록은 언어가 ko 라고 가정한다. 매장이 en-US 면 KRW 저장이 거부돼 빨개진다(검토 지적) —
  -- 현재 언어에 기대지 않고 명시한다(스위트는 롤백되므로 되돌릴 필요가 없다).
  perform save_settings(pg_temp.store(), '{"locale":"ko"}'::jsonb, pg_temp.settings_rev(pg_temp.store()));
  perform save_settings(pg_temp.store(), jsonb_build_object('unit_system', 'metric', 'cup_volume', 200, 'currency', 'KRW'), pg_temp.settings_rev(pg_temp.store()));
  perform pg_temp.eq('cup_volume 이 실제로 저장된다',
    (select cup_volume from settings where store_id = pg_temp.store()), 200, 0);
  perform pg_temp.raises('모르는 키는 거부 — 조용히 버리지 않는다',
    format('select save_settings(%L, %L::jsonb, %s)', pg_temp.store(), '{"theme":"dark"}', pg_temp.settings_rev(pg_temp.store())), '22000');
  -- 값의 뜻(검토 P2) — 키가 맞아도 뜻이 틀리면 거부.
  perform pg_temp.raises('unit_system 은 metric 뿐(1차)',
    format('select save_settings(%L, %L::jsonb, %s)', pg_temp.store(), '{"unit_system":"nonsense"}', pg_temp.settings_rev(pg_temp.store())), '22000');
  perform pg_temp.raises('컵 용량 음수는 거부',
    format('select save_settings(%L, %L::jsonb, %s)', pg_temp.store(), '{"cup_volume":-5}', pg_temp.settings_rev(pg_temp.store())), '22000');
  perform pg_temp.raises('모르는 통화는 거부',
    format('select save_settings(%L, %L::jsonb, %s)', pg_temp.store(), '{"currency":"???"}', pg_temp.settings_rev(pg_temp.store())), '22000');
  perform pg_temp.raises('모르는 언어는 거부',
    format('select save_settings(%L, %L::jsonb, %s)', pg_temp.store(), '{"locale":"xx-XX"}', pg_temp.settings_rev(pg_temp.store())), '22000');
  perform pg_temp.raises('자릿수 범위 밖은 거부',
    format('select save_settings(%L, %L::jsonb, %s)', pg_temp.store(), '{"unit_price_digits":9}', pg_temp.settings_rev(pg_temp.store())), '22000');
  perform pg_temp.raises('목표 이익률 100 초과는 거부',
    format('select save_settings(%L, %L::jsonb, %s)', pg_temp.store(), '{"default_target_profit_rate":150}', pg_temp.settings_rev(pg_temp.store())), '22000');
  perform pg_temp.eq_t('거부된 저장은 아무것도 안 바꿨다 — unit_system 그대로',
    (select unit_system from settings where store_id = pg_temp.store()), 'metric');
  perform save_settings(pg_temp.store(), '{"currency":"USD","locale":"en-US"}'::jsonb, pg_temp.settings_rev(pg_temp.store()));
  perform pg_temp.eq_t('목록 안의 통화·언어는 저장된다',
    (select currency || '/' || locale from settings where store_id = pg_temp.store()), 'USD/en-US');
  perform save_settings(pg_temp.store(), '{"currency":"KRW","locale":"ko"}'::jsonb, pg_temp.settings_rev(pg_temp.store()));

  -- ── 0168: 모양·JSON 타입 · 언어가 통화·자릿수를 정한다 ──
  perform pg_temp.raises('빈 {} 는 거부 — updated_at 만 바꾸는 저장은 없다',
    format('select save_settings(%L, %L::jsonb, %s)', pg_temp.store(), '{}', pg_temp.settings_rev(pg_temp.store())), '22000');
  perform pg_temp.raises('객체가 아니면 거부',
    format('select save_settings(%L, %L::jsonb, %s)', pg_temp.store(), '[1]', pg_temp.settings_rev(pg_temp.store())), '22000');
  perform pg_temp.raises('"yes" 는 참이 아니다 — 문자열 알림 값 거부',
    format('select save_settings(%L, %L::jsonb, %s)', pg_temp.store(), '{"alert_morning_summary":"yes"}', pg_temp.settings_rev(pg_temp.store())), '22000');
  perform pg_temp.raises('"abc" 컵 용량은 계약 오류(22000)지 원시 22P02 가 아니다',
    format('select save_settings(%L, %L::jsonb, %s)', pg_temp.store(), '{"cup_volume":"abc"}', pg_temp.settings_rev(pg_temp.store())), '22000');
  perform pg_temp.raises('"2" 자릿수도 숫자 타입이어야 한다',
    format('select save_settings(%L, %L::jsonb, %s)', pg_temp.store(), '{"money_digits":"2"}', pg_temp.settings_rev(pg_temp.store())), '22000');
  perform pg_temp.ok('거부된 저장은 알림 값을 안 바꿨다',
    (select alert_morning_summary from settings where store_id = pg_temp.store()) is not null);

  perform save_settings(pg_temp.store(), '{"locale":"en-US"}'::jsonb, pg_temp.settings_rev(pg_temp.store()));
  perform pg_temp.eq_t('언어만 보내도 통화·금액 자릿수가 함께 파생된다 (en-US → USD·2)',
    (select locale || '/' || currency || '/' || money_digits from settings where store_id = pg_temp.store()), 'en-US/USD/2');
  perform pg_temp.raises('언어와 다른 통화를 같이 보내면 거부',
    format('select save_settings(%L, %L::jsonb, %s)', pg_temp.store(), '{"locale":"ja","currency":"USD"}', pg_temp.settings_rev(pg_temp.store())), '22000');
  perform pg_temp.raises('현재 언어(en-US)와 다른 통화만 보내도 거부',
    format('select save_settings(%L, %L::jsonb, %s)', pg_temp.store(), '{"currency":"KRW"}', pg_temp.settings_rev(pg_temp.store())), '22000');
  perform pg_temp.raises('통화와 다른 금액 자릿수도 거부',
    format('select save_settings(%L, %L::jsonb, %s)', pg_temp.store(), '{"money_digits":0}', pg_temp.settings_rev(pg_temp.store())), '22000');
  perform pg_temp.eq_t('거부된 요청은 언어를 안 바꿨다', (select locale from settings where store_id = pg_temp.store()), 'en-US');
  perform save_settings(pg_temp.store(), '{"locale":"ko"}'::jsonb, pg_temp.settings_rev(pg_temp.store()));
  perform pg_temp.eq_t('ko → KRW·0 으로 돌아온다',
    (select locale || '/' || currency || '/' || money_digits from settings where store_id = pg_temp.store()), 'ko/KRW/0');
  perform pg_temp.eq('locale_defaults 는 core LOCALES 의 열 개를 안다',
    (select count(*) from unnest(array['ko','en-US','ja','de','ar-SA','ar-AE','vi','es-ES','es-MX','pt-BR']) l
      where exists (select 1 from locale_defaults(l))), 10, 0);
  perform pg_temp.ok('표의 CHECK — RPC 밖에서도 언어 키는 목록 안이어야 한다',
    exists (select 1 from pg_constraint where conname = 'settings_locale_ck' and convalidated));
  -- 조합도 표가 지킨다(0169) — service_role·소유자 직접 갱신으로 en-US/KRW/0 을 못 넣는다(검토 실측).
  set local role postgres;
  perform pg_temp.raises('직접 갱신으로도 언어·통화·자릿수 조합을 못 깬다 (23514)',
    format($q$update settings set locale = 'en-US' where store_id = %L$q$, pg_temp.store()), '23514');
  perform pg_temp.raises('통화만 바꿔도 조합 위반',
    format($q$update settings set currency = 'USD' where store_id = %L$q$, pg_temp.store()), '23514');
  set local role authenticated;
  perform pg_temp.eq_t('조합 위반이 거부된 뒤에도 행은 그대로',
    (select locale || '/' || currency || '/' || money_digits from settings where store_id = pg_temp.store()), 'ko/KRW/0');
  perform pg_temp.eq_t('기본 언어 키는 ko (예전 ko-KR 은 0168 이 옮겼다)',
    (select column_default from information_schema.columns
      where table_schema = 'public' and table_name = 'settings' and column_name = 'locale'), '''ko''::text');
end $t$;
